/* بيانات باب fiqhq: تُحمَّل عند أول فتح للقسم */
window.FIQHQ = {"ch":[{"id":"salat","t":"الطهارة والصلاة","d":"الآيات التي أصّلت أحكام الوضوء والتيمم والحيض، وأوقات الصلاة والقبلة والستر والقصر والجمعة."},{"id":"muamalat","t":"المعاملات المالية","d":"الربا والبيع والدَّين والإشهاد وأموال اليتامى والوصية والوفاء بالعقود."},{"id":"usra","t":"أحكام الأسرة","d":"النكاح والمهر والمحرَّمات والتعدد والطلاق والعدة والإيلاء والظهار والرضاع والنفقة واللعان."},{"id":"mirath","t":"المواريث","d":"آيات الفرائض: ميراث الأولاد والوالدين والزوجين والكلالة."},{"id":"hudud","t":"الجنايات والحدود","d":"القصاص والقتل الخطأ والعمد وحدود الزنا والقذف والسرقة والحرابة."},{"id":"at3ima","t":"الأطعمة والأشربة والذبائح","d":"المحرَّمات من المطعومات والذبائح والصيد وطعام أهل الكتاب وتحريم الخمر والميسر."},{"id":"siyasa","t":"الأيمان والقضاء والآداب والسياسة الشرعية","d":"كفارة اليمين والأمانة والحكم بالعدل وقتال البغاة والأمان، وآداب النظر واللباس."}],"tp":[{"id":"wudu","ch":"salat","t":"الوضوء والتيمم وشروط الطهارة للصلاة","e":"أعضاء الوضوء المأمور بغسلها ومسحها، وما تُرفع به الجنابة، والتيمم عند فقد الماء.","ay":[[5,6,6]],"q":[{"bk":"saadi","s":5,"ay":6,"x":"الرابع: اشتراط الطَّهارة لصحَّة الصلاة؛ لأنَّ الله أمر بها عند القيام إليها، والأصل في الأمر الوجوب. … السابع: الأمر بغسل الوجه، وهو ما تحصُل به المواجهة من منابت شعر الرأس المعتاد إلى ما انحدر من اللحيين والذقن طولاً ومن الأذن إلى الأذن عرضاً، ويدخل فيه المضمضة والاستنشاق بالسنة ، ويدخل فيه الشعور التي فيه، لكن إن كانت خفيفة؛ فلا بد من إيصال الماء إلى البشرة، وإن كانت كثيفةً؛ اكتفي بظاهرها. الثامن: الأمر بغسل اليدين، وأنَّ حدَّهما إلى المرفقين، و {إلى} كما قال جمهور المفسرين بمعنى مع؛ كقوله تعالى:{ولا تأكلوا أموالهم إلى أموالكم}، ولأن الواجب لا يتمُّ إلا بغسل جميع المرفق. التاسع: الأمر بمسح الرأس. … الثالث عشر: الأمر بغسل الرجلين إلى الكعبين، ويقال فيهما ما يقال في اليدين.","w":"السعدي","en":"Al-Sa'di: purity is a condition for the validity of prayer, because Allah commands it when rising for prayer; the face is washed, including rinsing the mouth and nose by the Sunna; the hands to the elbows (the elbow included); the head is wiped; and the feet are washed to the ankles."},{"bk":"qurtubi","s":5,"ay":6,"x":"قَالَ أَبُو حَنِيفَةَ وَأَبُو يُوسُفَ وَمُحَمَّدٌ: لَا يُجْزِئُ مَسْحُ الرَّأْسِ بأقل من ثلاث أَصَابِعَ، وَاخْتَلَفُوا فِي رَدِّ الْيَدَيْنِ عَلَى شَعْرِ الرَّأْسِ هَلْ هُوَ فَرْضٌ أَوْ سُنَّةٌ- بَعْدَ الْإِجْمَاعِ عَلَى أَنَّ الْمَسْحَةَ الْأُولَى فَرْضٌ بِالْقُرْآنِ- فَالْجُمْهُورُ عَلَى أَنَّهُ سُنَّةٌ.","w":"القرطبي","en":"Al-Qurtubi: Abu Hanifa, Abu Yusuf and Muhammad hold that wiping less than three fingers does not suffice. They differed on whether returning the hands over the hair is obligatory or a Sunna, after agreeing that the first wipe is obligatory by the Quran; most hold it is a Sunna."}]},{"id":"hayd","ch":"salat","t":"أحكام الحيض: اعتزال النساء في المحيض","e":"معنى المحيض وما يُعتزل فيه من النساء، ومتى يُباح بعد الطهر.","ay":[[2,222,222]],"q":[{"bk":"saadi","s":2,"ay":222,"x":"فأخبر تعالى أن الحيض أذى وإذا كان أذى فمن الحكمة أن يمنع الله تعالى عباده عن الأذى وحده، ولهذا قال:{فاعتزلوا النساء في المحيض}؛ أي: مكان الحيض وهو الوطء في الفرج خاصة فهذا المحرم إجماعاً، وتخصيص الاعتزال في المحيض يدل على أن مباشرة الحائض وملامستها في غير الوطء في الفرج جائز، لكن قوله:{ولا تقربوهن حتى يطهرن}؛ يدل على ترك المباشرة فيما قرب من الفرج وذلك فيما بين السرة والركبة ينبغي تركه كما كان النبي - صلى الله عليه وسلم -، إذا أراد أن يباشر امرأته وهي حائض أمرها أن تتزر فيباشرها ، وحد هذا الاعتزال وعدم القربان للحيض {حتى يطهرن}؛ أي: ينقطع دمهن، فإذا انقطع الدم زال المنع الموجود وقت جريانه، الذي كان لحله شرطان: انقطاع الدم والاغتسال منه …","w":"السعدي","en":"Al-Sa'di: menstruation is a harm, so Allah forbids the harm itself, which is intercourse in the private part, by consensus; other contact is permitted, though contact between navel and knees is best left, as the Prophet did by having his wife wear an izar; relations become lawful with two conditions: the blood stops and she washes."},{"bk":"qurtubi","s":2,"ay":222,"x":"وَقَالَ مَالِكٌ وَالشَّافِعِيُّ وَالْأَوْزَاعِيُّ وَأَبُو حَنِيفَةَ وَأَبُو يُوسُفَ وَجَمَاعَةٌ عَظِيمَةٌ مِنَ الْعُلَمَاءِ: لَهُ مِنْهَا مَا فَوْقَ الْإِزَارِ، لِقَوْلِهِ عَلَيْهِ السَّلَامُ لِلسَّائِلِ حِينَ سَأَلَهُ-: مَا يَحِلُّ لِي مِنَ امْرَأَتِي وَهِيَ حَائِضٌ؟","w":"القرطبي","en":"Al-Qurtubi: Malik, al-Shafi'i, al-Awza'i, Abu Hanifa, Abu Yusuf and a great group of scholars said that what is above the izar is permitted to him, citing the Prophet's answer to the one who asked what is lawful for him with his menstruating wife."}]},{"id":"awqat","ch":"salat","t":"أوقات الصلوات المفروضة","e":"الأوقات التي أُمر بإقامة الصلاة فيها، من دلوك الشمس إلى غسق الليل وقرآن الفجر.","ay":[[17,78,78],[4,103,103]],"q":[{"bk":"saadi","s":17,"ay":78,"x":"ففي هذه الآية ذكرُ الأوقات الخمسة للصَّلوات المكتوبات، وأن الصَّلوات الموقعة فيه فرائضُ؛ لتخصيصها بالأمر. وفيها أنَّ الوقت شرطٌ لصحَّة الصلاة، وأنَّه سببٌ لوجوبها؛ لأنَّ الله أمر بإقامتها لهذه الأوقات، وأنَّ الظهر والعصر يُجمعان، والمغرب والعشاء كذلك؛ للعذر؛ لأنَّ الله جمع وقتهما جميعاً. وفيه فضيلةُ صلاة الفجر، وفضيلة إطالة القراءة فيها، وأنَّ القراءة فيها ركنٌ؛ لأنَّ العبادة إذا سُمِّيت ببعض أجزائها؛ دلَّ على فرضيَّة ذلك.","w":"السعدي","en":"Al-Sa'di: the verse mentions the five obligatory prayer times; time is both a condition for the prayer's validity and a cause of its obligation; Dhuhr and Asr, and Maghrib and Isha, may be combined for an excuse; and it shows the merit of the Fajr prayer, of lengthening its recitation, and that recitation in it is a pillar."}]},{"id":"qibla","ch":"salat","t":"استقبال القبلة","e":"التوجه إلى المسجد الحرام في الصلاة حيثما كان المصلي.","ay":[[2,144,144]],"q":[{"bk":"saadi","s":2,"ay":144,"x":"ثم صرح له باستقبالها فقال:{فولِّ وجهك شطر المسجد الحرام}؛ والوجه: ما أقبل من بدن الإنسان {وحيث ما كنتم}؛ أي: من بر وبحر شرق وغرب جنوب وشمال، {فولوا وجوهكم شطره}؛ أي: جهته، ففيها اشتراط استقبال الكعبة للصلوات كلها فرضها ونفلها، وأنه إن أمكن استقبال عينها وإلا فيكفي شطرها وجهتها، وأن الالتفات بالبدن مبطل للصلاة؛ لأن الأمر بالشيء نهي عن ضده.","w":"السعدي","en":"Al-Sa'di: \"turn your face toward the Sacred Mosque\" makes facing the Kaaba a condition for all prayers, obligatory and voluntary; if its very direction cannot be known, facing its direction suffices; and turning the body away invalidates the prayer."}]},{"id":"satr","ch":"salat","t":"ستر العورة والزينة عند المسجد","e":"أخذ الزينة عند كل مسجد، وهو ستر العورة في الصلاة.","ay":[[7,31,31]],"q":[{"bk":"saadi","s":7,"ay":31,"x":"يقول تعالى بعدما أنزل على بني آدم لباساً يواري سوآتهم وريشاً: {يا بني آدم خُذوا زينتكم عند كل مسجدٍ}؛ أي: استروا عوراتكم عند الصلاة كلِّها فرضها ونفلها؛ فإن سترها زينة للبدن؛ كما أن كشفها يدع البدن قبيحاً مشوهاً، ويحتمل أنَّ المراد بالزينة هنا ما فوق ذلك من اللباس النظيف الحسن.","w":"السعدي","en":"Al-Sa'di: \"take your adornment at every mosque\" means cover your nakedness in all prayer, obligatory and voluntary, since covering is the body's adornment; and it may also mean wearing clean, good clothing."}]},{"id":"qasr","ch":"salat","t":"قصر الصلاة في السفر وصلاة الخوف","e":"الضرب في الأرض وقصر الصلاة، وكيفية صلاة الخوف.","ay":[[4,101,102]],"q":[{"bk":"saadi","s":4,"ay":101,"x":"وقوله:{فليس عليكم جناح أن تقصُروا من الصلاة}؛ أي: لا حرج ولا إثم عليكم في ذلك. … ويدلُّ على أفضلية القصر على الإتمام أمران: أحدُهما: ملازمة النبيِّ - صلى الله عليه وسلم - على القصر في جميع أسفاره. والثاني: أن هذا من باب التوسعة والترخيص والرحمة بالعباد، والله تعالى يُحِبُّ أن تُؤتى رُخَصُه، كما يكره أن تُؤتى معصيَتُه. … الثانية: أنَّ {من} تفيدُ التبعيض؛ ليعلم بذلك أن القصر لبعض الصلواتِ المفروضاتِ لا جميعها؛ فإنَّ الفجر والمغرب لا يُقصران، وإنما الذي يُقْصَر الصلاة الرباعية من أربع إلى ركعتين.","w":"السعدي","en":"Al-Sa'di: \"no blame on you if you shorten the prayer\" removes sin; shortening is better than completing, because the Prophet always shortened in his travels and because Allah loves His concessions to be taken; and \"from the prayer\" shows only four-rak'a prayers are shortened, to two."},{"bk":"qurtubi","s":4,"ay":101,"x":"وَحَكَى ابْنُ الْجَهْمِ أَنَّ أَشْهَبَ رَوَى عَنْ مَالِكٍ أَنَّ الْقَصْرَ فَرْضٌ، وَمَشْهُورُ مَذْهَبِهِ وَجُلُّ أَصْحَابِهِ وَأَكْثَرُ الْعُلَمَاءِ مِنَ السَّلَفِ وَالْخَلَفِ أَنَّ الْقَصْرَ سُنَّةٌ، وَهُوَ قَوْلُ الشَّافِعِيِّ، وَهُوَ الصَّحِيحُ عَلَى مَا يَأْتِي بَيَانُهُ إِنْ شَاءَ اللَّهُ.","w":"القرطبي","en":"Al-Qurtubi: Ibn al-Jahm reported from Ashhab from Malik that shortening is obligatory; but the well-known view of his school, most of his companions and most scholars is that it is a Sunna, which is also al-Shafi'i's view and the sound one."}]},{"id":"jumua","ch":"salat","t":"صلاة الجمعة وترك البيع عند النداء","e":"النداء لصلاة الجمعة والسعي إلى ذكر الله وترك البيع.","ay":[[62,9,10]],"q":[{"bk":"saadi","s":62,"ay":9,"x":"يأمر تعالى عباده المؤمنين بالحضور لصلاة الجمعة والمبادرة إليها من حين يُنادى لها والسعي إليها، والمراد بالسَّعْي هنا المبادرة [إليها] والاهتمام لها وجعلها أهمَّ الأشغال، لا العدو الذي قد نُهِيَ عنه عند المضيِّ إلى الصلاة. … ومنها: أنَّ الخطبتين يوم الجمعة فريضةٌ يجب حضورهما؛ لأنَّه فسَّر الذِّكر هنا بالخطبتين، فأمر الله بالمضيِّ إليه والسعي له. … ومنها: النهي عن البيع والشراء بعد نداء الجمعة وتحريم ذلك، وما ذاك إلاَّ لأنَّه يفوِّتُ الواجبَ ويَشْغَلُ عنه ، فدلَّ ذلك على أنَّ كلَّ أمر وإنْ كان مباحاً في الأصل، إذا كان ينشأ عنه تفويت واجبٍ؛ فإنَّه لا يجوز في تلك الحال.","w":"السعدي","en":"Al-Sa'di: Allah commands hastening to Friday prayer from the call, meaning prompt attention and not running; the two sermons are obligatory to attend; and buying and selling are forbidden after the call, since even a lawful matter becomes forbidden when it causes an obligation to be missed."}]},{"id":"riba","ch":"muamalat","t":"تحريم الربا وإنظار المعسر","e":"تحريم الربا وما يترتب عليه، وبيان أنه ليس كالبيع.","ay":[[2,275,276],[2,278,280]],"q":[{"bk":"saadi","s":2,"ay":275,"x":"وفي هذه الآية بيان لحكمة الربا وأنه يتضمن الظلم للمحتاجين بأخذ الزيادة وتضاعف الربا عليهم وهو واجب إنظارهم، ولهذا قال: {280 ـ 281}{وإن كان ذو عسرة فنظرة إلى ميسرة}؛ أي: وإن كان الذي عليه الدَّين معسراً لا يقدر على الوفاء وجب على غريمه أن يُنْظِره إلى ميسرة، وهو يجب عليه إذا حصل له وفاء بأي طريق مباح أن يوفي ما عليه، وإن تصدق عليه غريمه بإسقاط الدَّينِ كلِّه أو بعضه فهو خير له، ويهون على العبد التزام الأمور الشرعية واجتناب المعاملات الربوية والإحسان إلى المعسرين؛ عِلْمُه بأن له يوماً يرجع فيه إلى الله ويوفيه عمله ولا يظلمه مثقال ذرة.","w":"السعدي","en":"Al-Sa'di: the wisdom of prohibiting riba is that it wrongs the needy through extra payment and compounding; a debtor in hardship must be given respite until ease, and forgiving part or all of the debt is better; and remembering the return to Allah makes avoiding riba and kindness to the needy easy."},{"bk":"qurtubi","s":2,"ay":275,"x":"وَاخْتَلَفُوا فِي بَيْعِ التَّمْرَةِ الْوَاحِدَةِ بِالتَّمْرَتَيْنِ، وَالْحَبَّةِ الْوَاحِدَةِ مِنَ الْقَمْحِ بِحَبَّتَيْنِ، فَمَنَعَهُ الشَّافِعِيُّ وَأَحْمَدُ وَإِسْحَاقُ وَالثَّوْرِيُّ، وَهُوَ قِيَاسُ قَوْلِ مَالِكٍ وَهُوَ الصَّحِيحُ، لِأَنَّ مَا جَرَى الرِّبَا فِيهِ بِالتَّفَاضُلِ فِي كَثِيرِهِ دَخَلَ قَلِيلُهُ فِي ذَلِكَ قِيَاسًا وَنَظَرًا.","w":"القرطبي","en":"Al-Qurtubi: they differed over exchanging one date for two dates or one grain for two. Al-Shafi'i, Ahmad, Ishaq and al-Thawri forbade it, which is also the analogy of Malik's view and the sound one, since whatever is riba in large amounts is riba in small amounts."}]},{"id":"bay","ch":"muamalat","t":"البيع والتجارة عن تراضٍ وأكل المال بالباطل","e":"النهي عن أكل المال بالباطل وإباحة التجارة عن تراضٍ.","ay":[[4,29,29],[2,188,188]],"q":[{"bk":"saadi","s":4,"ay":29,"x":"ينهى تعالى عباده المؤمنين أن يأكلوا أموالهم بينهم بالباطل، وهذا يشمل أكلَها بالغصوب والسرقات وأخذَها بالقمار والمكاسب الرديئة، بل لعله يدخل في ذلك أكل مال نفسِك على وجه البطر والإسراف؛ لأن هذا من الباطل، وليس من الحق. ثم إنه لما حرَّم أكلها بالباطل؛ أباح لهم أكلها بالتجارات والمكاسب الخالية من الموانع المشتملة على الشروط من التراضي وغيره.{ولا تقتلوا أنفسكم}؛ أي: لا يقتل بعضكم بعضاً، ولا يقتل الإنسان نفسه، ويدخل في ذلك الإلقاء بالنفس إلى التهلكة وفعل الأخطار المفضية إلى التلف والهلاك {إنَّ الله كان بكم رحيماً}: ومن رحمته أن صان نفوسَكم وأموالكم ونهاكم عن إضاعتها وإتلافها ورتَّب على ذلك ما رتَّبه من الحدود.","w":"السعدي","en":"Al-Sa'di: Allah forbids consuming wealth unjustly, which includes usurpation, theft, gambling and wicked earnings, and even squandering one's own wealth; then He permits trade and earnings free of obstacles that fulfil conditions such as mutual consent."},{"bk":"qurtubi","s":4,"ay":29,"x":"السَّادِسَةُ- وَالْجُمْهُورُ عَلَى جَوَازِ الْغَبْنِ فِي التِّجَارَةِ، مِثْلَ أن يبيع رجل ياقوتة بِدِرْهَمٍ وَهِيَ تُسَاوِي مِائَةً فَذَلِكَ جَائِزٌ، وَأَنَّ الْمَالِكَ الصَّحِيحَ الْمِلْكِ جَائِزٌ لَهُ أَنْ يَبِيعَ مَالَهُ الْكَثِيرَ بِالتَّافِهِ الْيَسِيرِ، وَهَذَا مَا لَا اخْتِلَافَ فِيهِ بَيْنَ الْعُلَمَاءِ إِذَا عُرِفَ قَدْرُ ذَلِكَ، كَمَا تَجُوزُ الْهِبَةُ لَوْ وُهِبَ.","w":"القرطبي","en":"Al-Qurtubi: the majority hold that a price disparity is permitted in trade: if a man sells a ruby worth a hundred for one dirham, that is valid, as an owner may dispose of his property as he wishes, and there is no disagreement about this once the value is known."}]},{"id":"inzar","ch":"muamalat","t":"إنظار المعسر","e":"وجوب إنظار المدين المعسر، والتصدق عليه بالإبراء.","ay":[[2,280,280]],"q":[{"bk":"qurtubi","s":2,"ay":280,"x":"فيه تسع مسائل: الأول- قَوْلُهُ تَعَالَى: ﴿وَإِنْ كانَ ذُو عُسْرَةٍ﴾ لَمَّا حكم عز وجل لِأَرْبَابِ الرِّبَا بِرُءُوسِ أَمْوَالِهِمْ عِنْدَ الْوَاجِدِينَ لِلْمَالِ، حَكَمَ فِي ذِي الْعُسْرَةِ بِالنَّظِرَةِ إِلَى حَالِ الْمَيْسَرَةِ، وَذَلِكَ أَنَّ ثَقِيفًا لَمَّا طَلَبُوا أَمْوَالَهُمُ الَّتِي لَهُمْ عَلَى بَنِي الْمُغِيرَةِ شَكَوُا الْعُسْرَةَ- يعنى بنى المغيرة- وقالوا: ليس لنا شي، وَطَلَبُوا الْأَجَلَ إِلَى وَقْتِ ثِمَارِهِمْ، فَنَزَلَتْ هَذِهِ الْآيَةُ \"وَإِنْ كانَ ذُو عُسْرَةٍ\".","w":"القرطبي","en":"Al-Qurtubi: having ruled that creditors take back their capital from those who have means, Allah ruled respite until ease for the one in hardship; the verse was revealed when Thaqif demanded their money from Banu al-Mughira, who pleaded hardship and asked for time until their harvest."},{"bk":"qurtubi","s":2,"ay":280,"x":"الثَّانِيَةُ- قَوْلُهُ تَعَالَى: ﴿وَإِنْ كانَ ذُو عُسْرَةٍ﴾ مَعَ قَوْلِهِ \"وَإِنْ تُبْتُمْ فَلَكُمْ رُؤُسُ أَمْوالِكُمْ\" يَدُلُّ عَلَى ثُبُوتِ الْمُطَالَبَةِ لِصَاحِبِ الدَّيْنِ عَلَى الْمَدِينِ وَجَوَازِ أَخْذِ مَالِهِ بِغَيْرِ رِضَاهُ. وَيَدُلُّ عَلَى أَنَّ الْغَرِيمَ مَتَى امْتَنَعَ مِنْ أَدَاءِ الدَّيْنِ مَعَ الْإِمْكَانِ كَانَ ظَالِمًا، فَإِنَّ الله تعالى يقول: \"فَلَكُمْ رُؤُسُ أَمْوالِكُمْ\" فَجَعَلَ لَهُ الْمُطَالَبَةَ بِرَأْسِ مَالِهِ. فَإِذَا كَانَ لَهُ حَقُّ الْمُطَالَبَةِ فَعَلَى مَنْ عَلَيْهِ الدَّيْنُ لَا مَحَالَةَ وُجُوبُ قَضَائِهِ.","w":"القرطبي","en":"Al-Qurtubi: the verse shows that the creditor may demand payment and that a debtor who refuses to pay when able is unjust, because Allah gave the creditor the right to demand his capital; hence the debtor must repay."}]},{"id":"dayn","ch":"muamalat","t":"كتابة الدَّين والإشهاد والرهن","e":"كتابة الدَّين إلى أجل مسمًّى والإشهاد عليه والرهن في السفر.","ay":[[2,282,283]],"q":[{"bk":"saadi","s":2,"ay":282,"x":"ومنها: وجوب تسمية الأجل في جميع المداينات وحلول الإجارات. ومنها: أنه إذا كان الأجل مجهولاً فإنه لا يحل لأنه غرر وخطر فيدخل في الميسر. ومنها: أمره تعالى بكتابة الديون، وهذا الأمر قد يجب إذا وجب حفظ الحق كالذي للعبد عليه ولاية، كأموال اليتامى والأوقاف والوكلاء والأمناء، وقد يقارب الوجوب كما إذا كان الحق متمحضاً للعبد فقد يقوى الوجوب وقد يقوى الاستحباب، بحسب الأحوال المقتضية لذلك، وعلى كل حال فالكتابة من أعظم ما تحفظ به هذه المعاملات المؤجلة لكثرة النسيان ولوقوع المغالطات، وللاحتراز من الخونة الذين لا يخشون الله تعالى.","w":"السعدي","en":"Al-Sa'di: the term must be specified in all debts; an unknown term is not lawful as it is uncertainty; writing debts is commanded, sometimes obligatory (as with orphans' property and endowments) and at other times near-obligatory, and it is among the best ways of preserving deferred transactions against forgetfulness and fraud."},{"bk":"qurtubi","s":2,"ay":282,"x":"وَقَالَ مَالِكٌ وَأَبُو حَنِيفَةَ وَالشَّافِعِيُّ وَجُمْهُورُ الْعُلَمَاءِ: لَا تَجُوزُ شَهَادَةُ الْعَبْدِ، وَغَلَّبُوا نَقْصَ الرِّقِّ، وَأَجَازَهَا الشَّعْبِيُّ وَالنَّخَعِيُّ فِي الشَّيْءِ الْيَسِيرِ.","w":"القرطبي","en":"Al-Qurtubi: Malik, Abu Hanifa, al-Shafi'i and the majority hold that a slave's testimony is not accepted, as slavery is regarded as a deficiency; al-Sha'bi and al-Nakha'i allowed it for minor matters."}]},{"id":"yatim","ch":"muamalat","t":"حفظ مال اليتيم","e":"إيتاء اليتامى أموالهم وابتلاؤهم حتى يبلغوا النكاح وإيناس الرشد.","ay":[[4,2,2],[4,6,6]],"q":[{"bk":"saadi","s":4,"ay":2,"x":"ومن استبدال الخبيث بالطيِّب أن يأخذ الوليُّ من مال اليتيم النفيسِ ويجعلَ بدلَه من ماله الخسيسَ. وفيه الولايةُ على اليتيم؛ لأنَّ من لازم إيتاء اليتيم ماله ثبوتَ ولاية المؤتي على ماله. وفيه الأمرُ بإصلاح مال اليتيم؛ لأنَّ تمام إيتائِهِ مالَه حفظُه والقيامُ به بما يصلحه ويُنَمِّيه وعدم تعريضه للمخاوف والأخطار.","w":"السعدي","en":"Al-Sa'di: substituting the bad for the good includes a guardian taking the orphan's fine property and putting his own inferior in its place; the verse shows guardianship over the orphan and the command to improve and increase the orphan's wealth and protect it from risk."},{"bk":"qurtubi","s":4,"ay":6,"x":"وَقَالَ الزُّهْرِيُّ وَعَطَاءٌ: لَا حَدَّ عَلَى مَنْ لَمْ يَحْتَلِمْ، وَهُوَ قَوْلُ الشَّافِعِيِّ، وَمَالَ إِلَيْهِ مَالِكٌ مَرَّةً، وَقَالَ بِهِ بَعْضُ أَصْحَابِهِ.","w":"القرطبي","en":"Al-Qurtubi: al-Zuhri and 'Ata' said there is no penalty on one who has not had a wet dream, which is also al-Shafi'i's view; Malik inclined to it once, and some of his companions held it."}]},{"id":"wasiyya","ch":"muamalat","t":"الوصية","e":"كتب الوصية على من حضره الموت وترك خيراً، ووعيد من بدّلها.","ay":[[2,180,182]],"q":[{"bk":"saadi","s":2,"ay":180,"x":"أي: فرض الله عليكم يا معشر المؤمنين {إذا حضر أحدكم الموت}؛ أي: أسبابه كالمرض المشرف على الهلاك وحضور أسباب المهالك وكان قد {ترك خيراً }؛ وهو المال الكثير عرفاً فعليه أن يوصي لوالديه وأقرب الناس إليه بالمعروف على قدر حاله من غير سرف ولا اقتصار على الأبعد دون الأقرب، بل يرتبهم على القرب والحاجة ولهذا أتى فيه بأفعل التفضيل، وقوله:{حقًّا على المتقين}؛ دل على وجوب ذلك، لأن الحق هو الثابت، وقد جعله الله من موجبات التقوى. … فدلت هذه الآيات على الحث على الوصية وعلى بيان من هي له وعلى وعيد المبدل للوصية العادلة والترغيب في الإصلاح في الوصية الجائرة.","w":"السعدي","en":"Al-Sa'di: Allah prescribed that one near death who leaves considerable wealth should bequeath to parents and nearest kin fairly, without excess, ordering them by nearness and need; \"a duty upon the God-fearing\" indicates obligation; and the verses urge bequests and warn the one who alters a just bequest."},{"bk":"qurtubi","s":2,"ay":180,"x":"السَّابِعَةُ- ذَهَبَ الْجُمْهُورُ مِنَ الْعُلَمَاءِ إِلَى أَنَّهُ لَا يَجُوزُ لِأَحَدٍ أَنْ يُوصِيَ بِأَكْثَرِ مِنَ الثُّلُثِ إِلَّا أَبَا حَنِيفَةَ وَأَصْحَابَهُ فَإِنَّهُمْ قَالُوا: إِنْ لَمْ يَتْرُكِ الْمُوصِي وَرَثَةً جَازَ لَهُ أَنْ يُوصِيَ بِمَالِهِ كُلِّهِ.","w":"القرطبي","en":"Al-Qurtubi: the majority hold that no one may bequeath more than a third, except Abu Hanifa and his companions, who said that if the testator leaves no heirs he may bequeath all his wealth."}]},{"id":"uqud","ch":"muamalat","t":"الوفاء بالعقود","e":"الأمر بالوفاء بالعقود، وما أُحل من بهيمة الأنعام.","ay":[[5,1,1]],"q":[{"bk":"saadi","s":5,"ay":1,"x":"وهي مدنية {1} هذا أمر من الله تعالى لعباده المؤمنين بما يقتضيه الإيمان بالوفاء بالعقود؛ أي: بإكمالها وإتمامها وعدم نقضها ونقصها، وهذا شامل للعقود التي بين العبد وبين ربِّه من التزام عبوديته؛ والقيام بها أتم قيام، وعدم الانتقاص من حقوقها شيئاً، والتي بينه وبين الرسول بطاعته واتباعه، والتي بينه وبين الوالدين والأقارب ببرِّهم وصلتهم وعدم قطيعتهم، والتي بينه وبين أصحابه من القيام بحقوق الصحبة في الغنى والفقر واليسر والعسر، والتي بينه وبين الخلق من عقود المعاملات كالبيع والإجارة ونحوهما، وعقود التبرعات كالهبة ونحوها، بل والقيام بحقوق المسلمين التي عقدها الله بينهم في قوله:{إنما المؤمنون إخوة}، [بالتناصر] على الحقِّ والتعاون عليه والتآلف بين المسلمين وعدم التقاطع؛ فهذا الأمر شامل لأصول الدين وفروعه …","w":"السعدي","en":"Al-Sa'di: this is a command to fulfil contracts, meaning completing and not breaking them, covering contracts between a servant and his Lord, with the Messenger, with parents and kin, with companions, and between people in sales, leases and gifts; it embraces the roots and branches of religion."}]},{"id":"nikah","ch":"usra","t":"النكاح والمهر","e":"إيتاء النساء صدقاتهن نِحلة، وما يطيبن به نفساً عن شيء منه.","ay":[[4,4,4],[4,24,25]],"q":[{"bk":"saadi","s":4,"ay":4,"x":"ولما كان كثير من الناس يظلمون النساء ويهضمونهنَّ حقوقَهنَّ، خصوصاً الصداق الذي يكون شيئاً كثيراً ودفعةً واحدةً يشقُّ دفعُه للزوجةِ؛ أمرهم وحثَّهم على إيتاء النساء {صَدُقاتهنَّ}، أي: مهورهنَّ {نِحۡلَةً}؛ أي: عن طيب نفس وحال طمأنينة؛ فلا تمطلوهنَّ أو تبخسوا منه شيئاً؛ وفيه أن المهر يُدْفَع إلى المرأة إذا كانت مكلفةً، وأنها تملكه بالعقد؛ لأنه أضافه إليها، والإضافة تقتضي التمليك؛ {فإن طبن لكم عن شيء منه}؛ أي: من الصداق {نفساً}؛ بأن سَمَحْنَ لكم عن رضا واختيار بإسقاط شيء منه أو تأخيره أو المعاوضة عنه؛ {فكلوه هنيئاً مريئاً}؛ أي: لا حرج عليكم في ذلك ولا تَبِعَة.","w":"السعدي","en":"Al-Sa'di: since many people wrong women, especially over the dowry, Allah commands giving women their dowries willingly, not delaying or reducing any; the woman, if of age, owns it by the contract; and if she willingly forgoes some, it is lawful for him."}]},{"id":"muharramat","ch":"usra","t":"المحرَّمات من النساء","e":"الأمهات والبنات والأخوات والعمات والخالات وبنات الأخ والأخت، وأمهات الرضاعة والصهر.","ay":[[4,23,23]],"q":[{"bk":"saadi","s":4,"ay":23,"x":"فأما المحرمات في النسب؛ فهنَّ السبعُ اللاتي ذكرهنَّ الله: الأمُّ: يدخل فيها كلُّ من لها عليك ولادةٌ وإن بَعُدَتْ. … فهولاء هنَّ المحرَّمات من النسب بإجماع العلماء؛ كما هو نصُّ الآية الكريمة، وما عداهنَّ؛ فيدخُلُ في قولِهِ:{وأحِلَّ لكم ما وراء ذلكم}، وذلك كبنت العمَّة والعمِّ وبنت الخال والخالة.","w":"السعدي","en":"Al-Sa'di: those forbidden by lineage are the seven Allah mentioned: mothers (including grandmothers), daughters, sisters, paternal aunts, maternal aunts, brothers' daughters and sisters' daughters; by scholarly consensus, others (such as cousins) fall under \"lawful for you is what is beyond that\"."},{"bk":"qurtubi","s":4,"ay":23,"x":"وَاتَّفَقَ مَالِكٌ وَالثَّوْرِيُّ وَأَبُو حَنِيفَةَ وَالْأَوْزَاعِيُّ وَاللَّيْثُ عَلَى أَنَّهُ إِذَا مَسَّهَا بِشَهْوَةٍ حَرُمَتْ عَلَيْهِ أُمُّهَا وَابْنَتُهَا وَحَرُمَتْ عَلَى الْأَبِ وَالِابْنِ، وَهُوَ أَحَدُ قَوْلَيِ الشَّافِعِيِّ.","w":"القرطبي","en":"Al-Qurtubi: Malik, al-Thawri, Abu Hanifa, al-Awza'i and al-Layth agreed that if a man touches a woman with desire, her mother and daughter become forbidden to him, and she becomes forbidden to his father and son; this is one of al-Shafi'i's two views."}]},{"id":"taadud","ch":"usra","t":"التعدد والعدل بين الزوجات","e":"إباحة مثنى وثلاث ورباع بشرط العدل، والاقتصار على واحدة عند خوف الجور.","ay":[[4,3,3],[4,129,129]],"q":[{"bk":"saadi","s":4,"ay":3,"x":"وفي هذه الآية أنه ينبغي للإنسان أن يختار قبل النكاح، بل قد أباح له الشارعُ النظرَ إلى مَنْ يريد تزوجها؛ ليكون على بصيرة من أمره. ثم ذكر العدد الذي أباحه من النساء، فقال:{مثنى وثلاث ورباع}، أي: من أحب أن يأخذ ثنتين؛ فليفعل، أو ثلاثاً؛ فليفعل، أو أربعاً؛ فليفعل، ولا يزيد عليها؛ لأن الآية سيقت لبيان الامتنان؛ فلا يجوز الزيادة على غير ما سمى الله تعالى إجماعاً، وذلك لأن الرجل قد لا تندفع شهوتُه بالواحدة، فأبيح له واحدة بعد واحدة، حتى تبلغ أربعاً؛ لأن في الأربع غُنيةً لكل أحد إلا ما ندر، ومع هذا؛ فإنما يباح له ذلك إذا أمن على نفسه الجَوْر والظلم ووثق بالقيام بحقوقهن؛ فإن خاف شيئاً من هذا؛ فليقتصر على واحدة أو على ملك يمينه …","w":"السعدي","en":"Al-Sa'di: a man should choose carefully before marriage; he may look at the woman he intends to marry; two, three or four are allowed and no more, by consensus, since the verse was given as a favour; and this is only if he is sure he can be just, otherwise one suffices."},{"bk":"qurtubi","s":4,"ay":3,"x":"فال أَبُو عُمَرَ: قَالَ الشَّافِعِيُّ وَأَبُو حَنِيفَةَ وَأَصْحَابُهُمَا والثوري وَاللَّيْثُ بْنُ سَعْدٍ: لَا يَتَزَوَّجُ الْعَبْدُ أَكْثَرَ مِنَ اثْنَتَيْنِ، وَبِهِ قَالَ أَحْمَدُ وَإِسْحَاقُ.","w":"القرطبي","en":"Al-Qurtubi, citing Abu Umar: al-Shafi'i, Abu Hanifa and their companions, al-Thawri and al-Layth ibn Sa'd said a slave may not marry more than two, and so said Ahmad and Ishaq."}]},{"id":"talaq","ch":"usra","t":"الطلاق والخلع","e":"الطلاق مرتان، والإمساك بمعروف أو التسريح بإحسان، وافتداء المرأة.","ay":[[2,229,230],[65,1,1]],"q":[{"bk":"saadi","s":2,"ay":229,"x":"فأخبر تعالى أن {الطلاق}؛ أي: الذي تحصل به الرجعة، {مرتان}؛ ليتمكن الزوج إن لم يرد المضارة من ارتجاعها ويراجع رأيه في هذه المدة، وأما ما فوقها فليس محلاًّ لذلك؛ لأن من زاد على الثنتين فإما متجرئ على المحرم أو ليس له رغبة في إمساكها بل قصده المضارة، فلهذا أمر تعالى الزوج أن يمسك زوجته {بمعروف}؛ أي: عشرة حسنة ويجري مجرى أمثاله مع زوجاتهم، وهذا هو الأرجح، وإلا يسرحها ويفارقها، {بإحسان}؛ ومن الإحسان أن لا يأخذ على فراقه لها شيئاً من مالها لأنه ظلم وأخذ للمال في غير مقابلة بشيء، فلهذا قال:{ولا يحل لكم أن تأخذوا مما آتيتموهن شيئاً إلا أن يخافا أن لا يقيما حدود الله}؛ وهي المخالعة بالمعروف بأن كرهت الزوجة زوجها لخُلُقِه أو خَلْقِه أو نقص دينه …","w":"السعدي","en":"Al-Sa'di: revocable divorce is twice, so the husband can reconsider; then either retain her with kindness or release her gracefully, and part of grace is not taking her money; except when they fear not keeping Allah's limits, which is khul', where she dislikes him for his character, appearance or deficient religion."},{"bk":"qurtubi","s":2,"ay":229,"x":"وَقَدِ اخْتَلَفَ الْعُلَمَاءُ فِي هَذَا، فَقَالَ مَالِكٌ وَالشَّافِعِيُّ وَأَبُو حَنِيفَةَ وَأَصْحَابُهُمْ وَأَبُو ثَوْرٍ: يَجُوزُ أَنْ تَفْتَدِيَ مِنْهُ بِمَا تَرَاضَيَا عَلَيْهِ، كَانَ أَقَلَّ مِمَّا أعطاها أو أكثر منه.","w":"القرطبي","en":"Al-Qurtubi: Malik, al-Shafi'i, Abu Hanifa, their companions and Abu Thawr held that a wife may redeem herself by whatever they agree on, whether less or more than what he gave her."}]},{"id":"idda","ch":"usra","t":"العدة","e":"تربّص المطلقات ثلاثة قروء، وعدة المتوفى عنها زوجها، وعدة الحوامل.","ay":[[2,228,228],[2,234,234],[65,4,4]],"q":[{"bk":"saadi","s":2,"ay":228,"x":"أي: النساء [اللاتي] طلقهن أزواجهن {يتربصن بأنفسهن}؛ أي: ينتظرن ويعتددن مدة {ثلاثة قروء}؛ أي: حيض أو أطهار على اختلاف العلماء في المراد بذلك مع أن الصحيح أن القرء الحيض، ولهذه العدة عدة حكم منها العلم ببراءة الرحم إذا تكررت عليها ثلاثة الأقراء علم أنه ليس في رحمها حمل فلا يفضي إلى اختلاط الأنساب، ولهذا أوجب تعالى عليهن الإخبار عن، {ما خلق الله في أرحامهن}؛ وحرم عليهن كتمان ذلك من حمل أو حيض، لأن كتمان ذلك يفضي إلى مفاسد كثيرة فكتمان الحمل موجب أن تلحقه بغير من هو له رغبة فيه أو استعجالاً لانقضاء العدة فإذا ألحقته بغير أبيه حصل من قطع الرحم والإرث واحتجاب محارمه وأقاربه عنه …","w":"السعدي","en":"Al-Sa'di: divorced women wait three qur' (the sounder view is menstrual periods) so that it is known they are not pregnant and lineages are not confused; and they may not conceal what Allah created in their wombs, pregnancy or menses, as concealment leads to many harms."},{"bk":"saadi","s":2,"ay":234,"x":"أي: إذا توفي الزوج مكثت زوجته متربصة أربعة أشهر وعشرة أيام وجوباً، والحكمة في ذلك ليتبين الحمل في مدة الأربعة ويتحرك في ابتدائه في الشهر الخامس، وهذا العام مخصوص بالحوامل، فإن عدتهن بوضع الحمل، وكذلك الأمة عدتها على النصف من عدة الحرة شهران وخمسة أيام.","w":"السعدي","en":"Al-Sa'di: a widow waits four months and ten days as an obligation, so that pregnancy becomes clear; this general ruling is specific to the non-pregnant, since a pregnant woman's waiting ends with delivery."},{"bk":"qurtubi","s":2,"ay":228,"x":"السَّادِسَةُ- وَاخْتَلَفُوا هَلْ يُسَافِرُ بِهَا قَبْلَ أَنْ يَرْتَجِعَهَا، فَقَالَ مَالِكٌ وَالشَّافِعِيُّ: لَا يُسَافِرُ بِهَا حَتَّى يُرَاجِعَهَا، وَكَذَلِكَ قَالَ أَبُو حَنِيفَةَ وَأَصْحَابُهُ إِلَّا زُفَرَ فَإِنَّهُ رَوَى عنه الحسن ابن زِيَادٍ أَنَّ لَهُ أَنْ يُسَافِرَ بِهَا قَبْلَ الرَّجْعَةِ، وَرَوَى عَنْهُ عَمْرُو بْنُ خَالِدٍ، لَا يُسَافِرُ بِهَا حَتَّى يُرَاجِعَ.","w":"القرطبي","en":"Al-Qurtubi: they differed over whether a man may travel with his divorced wife before taking her back; Malik and al-Shafi'i said he may not until he takes her back, and so said Abu Hanifa and his companions except Zufar, from whom two different reports exist."}]},{"id":"ila","ch":"usra","t":"الإيلاء والظهار","e":"الحلف على ترك وطء الزوجة وتربص أربعة أشهر، وتشبيه الزوجة بالأم وكفارته.","ay":[[2,226,227],[58,2,4]],"q":[{"bk":"saadi","s":2,"ay":226,"x":"{وإن عزموا الطلاق}؛ أي امتنعوا من الفيئة فكان ذلك دليلاً على رغبتهم عنهن وعدم إرادتهم لأزواجهم، وهذا لا يكون إلا عزماً على الطلاق فإن حصل هذا الحق الواجب منه مباشرة وإلا أجبره الحاكم عليه أو قام به {فإن الله سميع عليم}؛ فيه وعيد وتهديد لمن يحلف هذا الحلف ويقصد بذلك المضارة والمشاقة. ويستدل بهذه الآية على أن الإيلاء خاص بالزوجة لقوله من نسائهم، وعلى وجوب الوطء في كل أربعة أشهر مرة؛ لأنه بعد الأربعة يجبر إما على الوطء أو على الطلاق، ولا يكون ذلك إلا لتركه واجباً.","w":"السعدي","en":"Al-Sa'di: if they refuse to return and resolve to divorce, the ruler compels either return or divorce; the verse shows that ila applies only to wives, and that relations are obliged once every four months, since after four months he is compelled to return or divorce."},{"bk":"saadi","s":58,"ay":2,"x":"وكان المعتاد عندَهم في هذا اللفظ الظهر، ولهذا سماه الله ظِهاراً، فقال:{الذين يظاهِرون منكم من نسائِهِم ما هنَّ أمَّهاتِهم}؛ أي: كيف يتكلَّمون بهذا الكلام الذي يعلمون أنَّه لا حقيقة له، فيشبهون أزواجهم بأمَّهاتِهم اللاَّتي ولدنهم؟! ولهذا عظَّم الله أمره وقبَّحه، فقال:{وإنَّهم لَيقولونَ منكراً من القول وزوراً}؛ أي: قولاً شنيعاً وكذباً ، {وإنَّ الله لَعَفُوٌّ غفورٌ}: عمَّن صَدَرَ منه بعضُ المخالفات فتداركَها بالتَّوْبَةِ النَّصوح.","w":"السعدي","en":"Al-Sa'di: zihar was customarily by saying \"you are to me like my mother's back\"; Allah condemns it, asking how they say what they know is untrue, and calls it \"an evil saying and a falsehood\", while He is forgiving toward one who repents sincerely."},{"bk":"qurtubi","s":2,"ay":226,"x":"وَقَالَ الْجُمْهُورُ: الْإِيلَاءُ هُوَ أَنْ يَحْلِفَ أَلَّا يَطَأَ أَكْثَرَ مِنْ أَرْبَعَةِ أَشْهُرٍ، فَإِنْ حَلَفَ عَلَى أَرْبَعَةٍ فَمَا دُونَهَا لَا يَكُونُ مُولِيًا، وَكَانَتْ عِنْدَهُمْ يَمِينًا مَحْضًا، لو وطئ في هذه المدة لم يكن عليه شي كَسَائِرِ الْأَيْمَانِ، هَذَا قَوْلُ مَالِكٍ وَالشَّافِعِيِّ وَأَحْمَدَ وَأَبِي ثَوْرٍ.","w":"القرطبي","en":"Al-Qurtubi: the majority said ila is swearing not to have relations for more than four months; an oath for four months or less is an ordinary oath. This is the view of Malik, al-Shafi'i, Ahmad and Abu Thawr."}]},{"id":"rada","ch":"usra","t":"الرضاع والحضانة","e":"إرضاع الأولاد حولين كاملين وما يجب للمرضعة، وتحريم الرضاعة.","ay":[[2,233,233],[4,23,23]],"q":[{"bk":"saadi","s":2,"ay":233,"x":"هذا خبر بمعنى الأمر تنزيلاً له منزلة المتقرر الذي لا يحتاج إلى أمر بأن {يرضعن أولادهن حولين}؛ ولما كان الحول يطلق على الكامل وعلى معظم الحول قال:{كاملين لمن أراد أن يتم الرضاعة}؛ فإذا تم للرضيع حولان فقد تم رضاعه وصار اللبن بعد ذلك بمنزلة سائر الأغذية، فلهذا كان الرضاع بعد الحولين غير معتبر لا يُحَرِّم.","w":"السعدي","en":"Al-Sa'di: mothers suckle their children two full years; once the baby completes two years, its nursing is complete and milk becomes like other food, so suckling after two years is not counted and does not create kinship."},{"bk":"qurtubi","s":2,"ay":233,"x":"التَّاسِعَةُ- فِي هَذِهِ الْآيَةِ دَلِيلٌ لِمَالِكٍ عَلَى أَنَّ الْحَضَانَةَ لِلْأُمِّ، فَهِيَ فِي الْغُلَامِ إِلَى الْبُلُوغِ، وَفِي الْجَارِيَةِ إِلَى النِّكَاحِ، وَذَلِكَ حَقٌّ لَهَا، وَبِهِ قَالَ أَبُو حَنِيفَةَ.","w":"القرطبي","en":"Al-Qurtubi: in this verse is evidence for Malik that custody belongs to the mother: for a boy until adulthood and for a girl until marriage, and it is her right; Abu Hanifa held the same."}]},{"id":"nafaqa","ch":"usra","t":"النفقة والسكنى للمطلقات","e":"إسكان المطلقات والإنفاق على أولات الحمل منهن بحسب سعة الزوج.","ay":[[65,6,7]],"q":[{"bk":"saadi","s":65,"ay":6,"x":"تقدَّم أنَّ الله نهى عن إخراج المطلَّقات عن البيوت، وهنا أمر بإسكانهنَّ وقدر إسكانهنَّ بالمعروف، وهو البيت الذي يسكنه مثلُه ومثلُها؛ بحسب وُجْد الزوج وعسره، {ولا تُضارُّوهنَّ لِتُضَيِّقوا عليهنَّ}؛ أي: لا تضاروهنَّ عند سكناهنَّ بالقول أو الفعل؛ لأجل أن يمللنَ فيخرجنَ من البيوت قبل تمام العدة، فتكونوا أنتم المخرِجين لهنَّ. وحاصل هذا أنَّه نهى عن إخراجهنَّ ونهاهنَّ عن الخروج، وأمر بسكناهنَّ على وجهٍ لا يحصلُ عليهن ضررٌ ولا مشقَّة، وذلك راجعٌ إلى العرف. … ثم قدَّر تعالى النفقة بحسب حال الزوج، فقال:{لِيُنفِقۡ ذو سَعةٍ من سعتِهِ}؛ أي: لينفق الغنيُّ من غناه؛ فلا ينفق نفقة الفقراء، {ومن قُدِرَ عليه رزقُه}؛ أي: ضيِّق عليه، {فلينفِقۡ ممَّا آتاه الله}: من الرزق.","w":"السعدي","en":"Al-Sa'di: Allah commands housing divorced women suitably, according to the husband's ease or hardship, and forbids harming them to make them leave; then He measures maintenance by the husband's means: the wealthy spends from his wealth, and the straitened from what Allah gave him."},{"bk":"qurtubi","s":65,"ay":6,"x":"قُلْتُ: اخْتَلَفَ الْعُلَمَاءُ فِي الْمُطَلَّقَةِ ثَلَاثًا عَلَى ثَلَاثَةِ أَقْوَالٍ فَمَذْهَبُ مَالِكٍ وَالشَّافِعِيِّ: أَنَّ لَهَا السُّكْنَى وَلَا نَفَقَةَ لَهَا.","w":"القرطبي","en":"Al-Qurtubi: scholars differed over a woman divorced three times in three views; the view of Malik and al-Shafi'i is that she has housing but no maintenance."}]},{"id":"liaan","ch":"usra","t":"اللعان","e":"رمي الأزواج بلا شهداء وأيمان الملاعنة التي تدرأ الحد.","ay":[[24,6,9]],"q":[{"bk":"saadi","s":24,"ay":6,"x":"{والذين يرمون أزواجهم}؛ أي: الأحرار لا المملوكات {ولم يكن لهم}: على رَمْيِهِم بذلك {شهداءُ إلاَّ أنفسُهُم}: بأن لم يُقيموا شهداء على ما رموهم به، {فشهادةُ أحدِهم أربعُ شهاداتٍ بالله إنَّه لَمِنَ الصادقين}: سماها شهادةً لأنها نائبةٌ منابَ الشهود؛ بأن يقولَ: أشهدُ بالله أنِّي لمن الصادقين فيما رميتُها به. {والخامسةُ أنَّ لعنةَ الله عليه إن كان من الكاذبين}؛ أي: يزيد في الخامسة مع الشهادة المذكورة مؤكِّداً تلك الشهادات بأن يَدْعُوَ على نفسه باللعنة إنْ كان كاذباً؛ فإذا تَمَّ لعانُه؛ سقط عنه حدُّ القذف. … فيه قولانِ للعلماء، الذي يدلُّ عليه الدليل أنه يُقام عليها الحدُّ؛ بدليل قوله:{ويدرؤوا عنها العذابَ أن تَشۡهَدَ ...","w":"السعدي","en":"Al-Sa'di: when a husband accuses his wife without witnesses, he swears four times that he is truthful and a fifth time invoking Allah's curse if he lies; once complete, the slander penalty falls from him; whether the penalty is then applied to her is disputed, and the evidence indicates it is."},{"bk":"qurtubi","s":24,"ay":6,"x":"وَقَالَ أَبُو حَنِيفَةَ: لَا يَصِحُّ اللِّعَانُ إِلَّا مِنْ زَوْجَيْنِ حُرَّيْنِ مُسْلِمَيْنِ، وَذَلِكَ لِأَنَّ اللِّعَانَ عِنْدَهُ شَهَادَةٌ، وَعِنْدَنَا وَعِنْدَ الشَّافِعِيِّ يَمِينٌ، فَكُلُّ مَنْ صَحَّتْ يَمِينُهُ صَحَّ قَذْفُهُ وَلِعَانُهُ.","w":"القرطبي","en":"Al-Qurtubi: Abu Hanifa said li'an is valid only between free Muslim spouses, since for him it is testimony; for the Maliki school and al-Shafi'i it is an oath, so whoever's oath is valid, his accusation and li'an are valid."}]},{"id":"awlad","ch":"mirath","t":"ميراث الأولاد والوالدين","e":"نصيب الأولاد والوالدين في التركة بعد الوصية والدَّين.","ay":[[4,11,11]],"q":[{"bk":"saadi","s":4,"ay":11,"x":"ثم ذكر كيفية إرثهم، فقال:{للذكر مثل حظ الأنثيين}؛ أي: الأولاد للصلب والأولاد للابن، للذكر مثل حظِّ الأنثيين إن لم يكن معهم صاحبُ فرض، أو ما أبقت الفروض يقتسمونه كذلك، وقد أجمع العلماء على ذلك، وأنه مع وجود أولاد الصلب؛ فالميراث لهم، وليس لأولاد الابن شيء؛ حيث كان أولاد الصلب ذكوراً وإناثاً. … وقد ذكره بقوله:{فإن كنَّ نساءً فوق اثنتين}؛ أي: بنات صلب أو بنات ابن ثلاثاً فأكثر؛ {فلهن ثلثا ما ترك وإن كانت واحدة}؛ أي: بنتاً أو بنت ابن؛ {فلها النصف}.","w":"السعدي","en":"Al-Sa'di: the male receives the share of two females, among full children or sons' children, unless a fixed-share heir is present; scholars agree that when children of the deceased exist, grandchildren receive nothing; and if there are three or more daughters they take two thirds, and a single daughter takes half."},{"bk":"qurtubi","s":4,"ay":11,"x":"وَذَهَبَ عَلِيُّ بْنُ أَبِي طَالِبٍ وَزَيْدُ وَابْنُ مَسْعُودٍ إِلَى تَوْرِيثِ الْجَدِّ مَعَ الْإِخْوَةِ، وَلَا يُنْقَصُ مِنَ الثُّلُثِ مَعَ الْإِخْوَةِ لِلْأَبِ وَالْأُمِّ أَوْ لِلْأَبِ إِلَّا مَعَ ذَوِي الْفُرُوضِ، فَإِنَّهُ لَا يُنْقَصُ مَعَهُمْ مِنَ السُّدُسِ شَيْئًا فِي قَوْلِ زَيْدٍ. وَهُوَ قَوْلُ مَالِكٍ وَالْأَوْزَاعِيِّ وَأَبِي يُوسُفَ وَمُحَمَّدٍ وَالشَّافِعِيِّ وَكَانَ عَلِيٌّ يُشْرِكُ بَيْنَ الْإِخْوَةِ وَالْجَدِّ إِلَى السُّدُسِ وَلَا يُنْقِصُهُ مِنَ السُّدُسِ شَيْئًا مَعَ ذَوِي الْفَرَائِضِ وَغَيْرِهِمْ.","w":"القرطبي","en":"Al-Qurtubi: this is the view of Malik, al-Awza'i, Abu Yusuf, Muhammad and al-Shafi'i. Ali treated brothers and the grandfather as partners down to a sixth and did not reduce him below a sixth."}]},{"id":"azwaj","ch":"mirath","t":"ميراث الزوجين والكلالة","e":"نصيب الزوجين، وميراث الكلالة من الإخوة والأخوات.","ay":[[4,12,12],[4,176,176]],"q":[{"bk":"ibnkathir","s":4,"ay":12,"x":"يَقُولُ تَعَالَى: وَلَكُمْ -أَيُّهَا الرِّجَالُ-نِصْفُ مَا تَرَكَ أَزْوَاجُكُمْ إِذَا مُتْن عَنْ غَيْرِ وَلَدٍ، فَإِنْ كَانَ لَهُنَّ وَلَدٌ فَلَكُمُ الرُّبُعُ مِمَّا تَرَكْنَ مِنْ بَعْدِ [وَصِيَّةٍ] يُوصِينَ بِهَا أَوْ دِينٍ. وَقَدْ تَقَدَّمَ أَنَّ الدَّيْنَ مُقَدَّمٌ عَلَى الْوَصِيَّةِ، وَبَعْدَهُ الْوَصِيَّةُ ثُمَّ الْمِيرَاثُ، وَهَذَا أَمْرٌ مُجْمَعٌ عَلَيْهِ بَيْنَ الْعُلَمَاءِ، وَحُكْمُ أَوْلَادِ الْبَنِينَ وَإِنْ سَفُلُوا حُكْمُ أَوْلَادِ الصُّلْبِ. ثُمَّ قَالَ: ﴿وَلَهُنَّ الرُّبُعُ مِمَّا تَرَكْتُمْ [إِنْ لَمْ يَكُنْ لَكُمْ وَلَدٌ فَإِنْ كَانَ لَكُمْ وَلَدٌ فَلَهُنَّ الثُّمُنُ مِمَّا تَرَكْتُمْ] ﴾ إِلَخْ، وَسَوَاءٌ فِي الرُّبُعِ أَوِ الثُّمُنِ الزَّوْجَةُ والزوجتان الاثنتان والثلاث والأربع يشتركن فيه.","w":"ابن كثير","en":"Ibn Kathir: husbands receive half of what wives leave if they have no children, and a quarter if they have; debt comes before the bequest and then the inheritance, by consensus; wives receive a quarter if there is no child and an eighth if there is, shared equally among co-wives."},{"bk":"saadi","s":4,"ay":176,"x":"؛ أي: نصف متروكات أخيها من نقودٍ وعقارٍ وأثاثٍ وغير ذلك، وذلك من بعد الدَّين والوصيَّة؛ كما تقدم. {وهو}؛ أي: أخوها الشقيق أو الذي للأب، {يَرِثُها إن لم يكن لها ولد}، ولم يُقَدِّر له إرثاً لأنه عاصبٌ فيأخذ مالها كلَّه إن لم يكن صاحبُ فرض ولا عاصب يشارِكه أو ما أبقت الفروض. {فإن كانتا}؛ أي: الأختان، {اثنتين}؛ أي: فما فوق {فلهما الثُّلثانِ مما تَرَكَ، وإن كانوا إخوةً رجالاً ونساءً}؛ أي: اجتمع الذُّكور من الإخوة لغير أمٍّ مع الإناث، {فللذَّكر مثلُ حظِّ الأنثيين}: فيسقُط فرض الإناث ويُعَصِّبُهنَّ إخوتُهن.","w":"السعدي","en":"Al-Sa'di: a sister receives half of what her brother leaves after debt and bequest; he inherits all from her if she has no child; two or more sisters take two thirds; and when brothers and sisters are together the male takes the share of two females."}]},{"id":"qisas","ch":"hudud","t":"القصاص","e":"فرض القصاص في القتلى والعفو إلى الدية، وحكمته في حفظ الحياة.","ay":[[2,178,179]],"q":[{"bk":"saadi","s":2,"ay":178,"x":"وفي هذه الآية دليل على أن الأصل وجوب القود في القتل وأن الدية بدل عنه، فلهذا قال:{فمن عفي له من أخيه شيء}؛ أي: عفا ولي المقتول عن القاتل إلى الدية أو عفا بعض الأولياء فإنه يسقط القصاص وتجب الدية وتكون الخيرة في القود واختيار الدية إلى الولي، فإذا عفا عنه، وجب على الولي؛ أي ولي المقتول أن يتبع القاتل، {بالمعروف}؛ من غير أن يشق عليه ولا يحمله ما لا يطيق، بل يحسن الاقتضاء والطلب ولا يحرجه.","w":"السعدي","en":"Al-Sa'di: the verse shows the principle is retribution, with blood money as a substitute; if the victim's guardian pardons in return for blood money, retribution lapses and the choice rests with him; and he must then pursue the killer kindly, without burdening him."}]},{"id":"khata","ch":"hudud","t":"القتل الخطأ والدية والكفارة","e":"تحرير رقبة مؤمنة ودية مسلَّمة إلى أهل المقتول خطأً، والصيام عند العجز.","ay":[[4,92,92]],"q":[{"bk":"saadi","s":4,"ay":92,"x":"وأما الدِّية؛ فإنها تجب على عاقلة القاتل في الخطأ وشبه العمد. {مسلَّمةٌ إلى أهله}: جبراً لقلوبهم. والمراد بـ {أهله} هنا هم ورثتُهُ؛ فإن الورثة يرثون ما ترك الميت، فالدِّية داخلةٌ فيما ترك، وللدِّيةِ تفاصيل كثيرة مذكورة في كتب الفقه.","w":"السعدي","en":"Al-Sa'di: blood money for accidental and quasi-intentional killing falls on the killer's 'aqila (kin group) and is handed to the victim's family, meaning his heirs, to console their hearts; its many details are in the books of fiqh."},{"bk":"qurtubi","s":4,"ay":92,"x":"وَلَا يُجْزِئُ عِنْدَ مَالِكٍ وَالشَّافِعِيِّ وَأَكْثَرِ الْعُلَمَاءِ أَقْطَعُ إِحْدَى الْيَدَيْنِ أَوْ إِحْدَى الرِّجْلَيْنِ، وَيُجْزِئُ عِنْدَ أَبِي حَنِيفَةَ وَأَصْحَابِهِ.","w":"القرطبي","en":"Al-Qurtubi: according to Malik, al-Shafi'i and most scholars, a slave missing one hand or one foot does not suffice for freeing; Abu Hanifa and his companions deem it sufficient."}]},{"id":"amd","ch":"hudud","t":"القتل العمد ووعيده","e":"وعيد من قتل مؤمناً متعمداً وما يتصل به من الكفارة.","ay":[[4,93,93]],"q":[{"bk":"saadi","s":4,"ay":93,"x":"وهذا الوعيد له حكم أمثاله من نصوص الوعيد على بعض الكبائر والمعاصي بالخلود في النار أو حرمان الجنة. وقد اختلف الأئمة رحمهم الله في تأويلها، مع اتفاقهم على بطلان قول الخوارج والمعتزلة الذين يخلِّدونهم في النار ولو كانوا موحِّدين، والصواب في تأويلها ما قاله الإمام المحقِّق شمس الدين ابن القيم رحمه الله في «المدارج» ؛ فإنه قال بعد ما ذكر تأويلات الأئمة في ذلك وانتقدها، فقال: وقالت فرقةٌ: إن هذه النصوص وأمثالها مما ذُكِرَ فيه المقتضي للعقوبة، ولا يلزم من وجود مقتضى الحكم وجودُه؛ فإن الحكم إنما يتمُّ بوجود مقتضيه وانتفاء موانعه، وغاية هذه النصوص الإعلام بأن كذا سببٌ للعقوبة ومقتضٍ لها، وقد قام الدليل على ذِكْرِ الموانع؛ فبعضُها بالإجماع وبعضُها بالنص؛ فالتوبة مانعٌ بالإجماع …","w":"السعدي","en":"Al-Sa'di: this warning is like other texts about eternal punishment for major sins; scholars differed on its interpretation while agreeing against the Khawarij and Mu'tazila, who make them eternally in the Fire; the sound view, as Ibn al-Qayyim explained, is that a warning states a cause for punishment, which may be removed by obstacles such as repentance by consensus."},{"bk":"qurtubi","s":4,"ay":93,"x":"وَقَدْ أَجْمَعُوا عَلَى أَنَّ عَلَى الْقَاتِلِ خَطَأً الْكَفَّارَةَ، وَاخْتَلَفُوا فِيهَا فِي قَتْلِ الْعَمْدِ، فَكَانَ مَالِكٌ وَالشَّافِعِيُّ يَرَيَانِ عَلَى قَاتِلِ الْعَمْدِ الْكَفَّارَةَ كَمَا فِي الْخَطَأِ.","w":"القرطبي","en":"Al-Qurtubi: they agreed that the accidental killer must offer expiation; they disagreed about the intentional killer; Malik and al-Shafi'i held that he must offer expiation as in accidental killing."}]},{"id":"zina","ch":"hudud","t":"حد الزنا","e":"جلد الزاني والزانية مائة جلدة، وشهود طائفة من المؤمنين.","ay":[[24,2,3]],"q":[{"bk":"saadi","s":24,"ay":2,"x":"هذا الحكم في الزاني والزانية البكرين: أنَّهما يُجلد كلٌّ منهما مائة جلدةٍ، وأما الثيِّب؛ فقد دلَّت السنة الصحيحة المشهورة أنَّ حدَّه الرجم. ونهانا تعالى أن تأخُذَنا رأفةٌ بهما في دين الله تمنعُنا من إقامة الحدِّ عليهما، سواء رأفة طبيعيَّة، أو لأجل قرابة أو صداقة أو غير ذلك، وأنَّ الإيمان موجبٌ لانتفاء هذه الرأفة المانعة من إقامة أمرِ الله؛ فرحمتُه حقيقةً بإقامة الحدِّ عليه، فنحنُ وإن رَحِمْناه لِجَرَيان القدر عليه؛ فلا نَرْحَمُه من هذا الجانب. وأمَرَ تعالى أن يَحْضُرَ عذابَ الزانيين {طائفةٌ}؛ أي: جماعة من المؤمنين؛ ليشتهر ويحصُلَ بذلك الخزي والارتداع، وليشاهدوا الحدَّ فعلاً؛ فإنَّ مشاهدة أحكام الشرع بالفعل مما يَقْوى به العلم، ويستقرُّ بها الفهم، ويكونُ أقربَ لإصابة الصواب؛ فلا يزادُ فيه ولا ينقص.","w":"السعدي","en":"Al-Sa'di: unmarried adulterers are each flogged a hundred lashes, while the sound Sunna shows that the married adulterer is stoned; we are forbidden to let pity prevent applying the penalty; and a group of believers must witness it, so that it deters and shows the law applied in practice."},{"bk":"qurtubi","s":24,"ay":2,"x":"الْحَادِيَةَ عَشْرَةَ- اخْتَلَفَ الْعُلَمَاءُ فِي تجريد المجلود في الزنى، فَقَالَ مَالِكٌ وَأَبُو حَنِيفَةَ وَغَيْرُهُمَا: يُجَرَّدُ، وَيُتْرَكُ عَلَى الْمَرْأَةِ مَا يَسْتُرُهَا دُونَ مَا يَقِيهَا الضَّرْبَ.","w":"القرطبي","en":"Al-Qurtubi: scholars differed over stripping the one flogged for zina; Malik, Abu Hanifa and others said he is stripped, while the woman is left what covers her but not what protects from the blow."}]},{"id":"qadhf","ch":"hudud","t":"حد القذف","e":"جلد من يرمون المحصنات ثمانين جلدة ورد شهادتهم وفسقهم، إلا من تاب.","ay":[[24,4,5]],"q":[{"bk":"saadi","s":24,"ay":4,"x":": على ما رموا به {بأربعة شهداء}؛ أي: رجال عدول يشهدون بذلك صريحاً {فاجۡلُدوهم ثمانينَ جلدةً}: بسوطٍ متوسطٍ يؤلِمُ فيه، ولا يبالِغُ بذلك حتى يُتْلِفَه؛ لأن القصد التأديب لا الإتلاف. وفي هذا تقريرُ حدِّ القذف، ولكن بشرط أن يكون المقذوف كما قال تعالى محصناً مؤمناً، وأما قذف غير المحصن؛ فإنَّه يوجِبُ التعزير، {ولا تَقۡبَلوا لهم شهادةً أبداً}؛ أي: لهم عقوبة أخرى، وهو أنَّ شهادة القاذف غير مقبولة، ولو حُدَّ على القَذْفِ، حتى يتوبَ؛ كما يأتي.","w":"السعدي","en":"Al-Sa'di: whoever accuses chaste believers and does not bring four upright witnesses is flogged eighty lashes with a medium whip meant to discipline, not destroy; slandering one who is not chaste only requires discretionary punishment; and the slanderer's testimony is rejected until he repents."},{"bk":"qurtubi","s":24,"ay":4,"x":"التَّاسِعَةُ- قَالَ مَالِكٌ وَالشَّافِعِيُّ: مَنْ قَذَفَ مَنْ يَحْسَبُهُ عَبْدًا فَإِذَا هُوَ حُرٌّ فَعَلَيْهِ الْحَدُّ، وَقَالَهُ الْحَسَنُ الْبَصْرِيُّ وَاخْتَارَهُ ابْنُ الْمُنْذِرِ.","w":"القرطبي","en":"Al-Qurtubi: Malik and al-Shafi'i said that one who slanders a person he thinks is a slave who is actually free is subject to the penalty; so said al-Hasan al-Basri, and Ibn al-Mundhir favoured it."}]},{"id":"sariqa","ch":"hudud","t":"حد السرقة","e":"قطع يد السارق والسارقة جزاءً بما كسبا، وقبول التوبة.","ay":[[5,38,39]],"q":[{"bk":"saadi","s":5,"ay":38,"x":"السارق: هو مَن أخذ مال غيره المحترم خفية بغير رضاه، وهو من كبائر الذنوب الموجبة لترتُّب العقوبة الشنيعة، وهو قطع اليد اليمنى؛ كما هو في قراءة بعض الصحابة، وحدُّ اليد عند الإطلاق من الكوع؛ فإذا سَرَقَ؛ قُطِعَتْ يدُهُ من الكوع وحُسِمَتْ في زيت لتنسدَّ العروق فيقف الدم. … ومنها: أنه لا بدَّ أن يكون المسروق نصاباً، وهو ربع دينار أو ثلاثة دراهم أو ما يساوي أحدهما؛ فلو سرق دون ذلك؛ فلا قطع عليه، ولعل هذا يؤخذ من لفظ السرقة ومعناها؛ فإنَّ لفظ السرقة أخذ الشيء على وجهٍ لا يمكن الاحترازُ منه، وذلك أن يكون المال محرزاً؛ فلو كان غير مُحْرَزٍ؛ لم يكن ذلك سرقة شرعية.","w":"السعدي","en":"Al-Sa'di: a thief is one who secretly takes another's protected property without consent, a major sin; the penalty is cutting the right hand at the wrist; the Sunna requires that the stolen item reach a minimum value (a quarter dinar or three dirhams) and be kept in a secure place."},{"bk":"qurtubi","s":5,"ay":38,"x":"السَّابِعَةُ- وَالْقَبْرُ وَالْمَسْجِدُ حِرْزٌ، فَيُقْطَعُ النَّبَّاشُ عِنْدَ الْأَكْثَرِ، وَقَالَ أَبُو حَنِيفَةَ: لَا قَطْعَ عَلَيْهِ، لِأَنَّهُ سَرَقَ مِنْ غَيْرِ حِرْزٍ مَالًا مُعَرَّضًا لِلتَّلَفِ لَا مَالِكَ لَهُ، لِأَنَّ الْمَيِّتَ لَا يَمْلِكُ.","w":"القرطبي","en":"Al-Qurtubi: a grave and a mosque count as secure places, so the grave-robber is cut according to most scholars; Abu Hanifa said no cutting, since he stole from a non-secure place property liable to decay that has no owner, as the dead cannot own."}]},{"id":"hiraba","ch":"hudud","t":"الحرابة وقطع الطريق","e":"جزاء الذين يحاربون الله ورسوله ويسعون في الأرض فساداً، واستثناء التائبين.","ay":[[5,33,34]],"q":[{"bk":"saadi","s":5,"ay":33,"x":"المحاربون لله ورسوله هم الذين بارزوه بالعداوة وأفسدوا في الأرض بالكُفر والقتل وأخذ الأموال وإخافة السبل، والمشهور أنَّ هذه الآية الكريمة في أحكام قُطَّاع الطريق الذين يعرضون للناس في القرى والبوادي فيغصبونهم أموالَهم ويقتُلونهم ويخيفونهم، فيمتَنِع الناسُ من سلوك الطريق التي هم بها، فتنقَطِع بذلك. فأخبر الله أنَّ جزاءهم ونَكالهم عند إقامة الحدِّ عليهم أن يُفعلَ بهم واحدٌ من هذه الأمور.","w":"السعدي","en":"Al-Sa'di: those who wage war on Allah and His Messenger spread corruption by unbelief, killing, seizing wealth and terrorising roads; the verse is known to concern highway robbers who rob and kill people and frighten them from travelling; and Allah states their recompense, one of the listed penalties."},{"bk":"qurtubi","s":5,"ay":33,"x":"وَقَالَ مَالِكٌ وَالشَّافِعِيُّ وَأَبُو ثَوْرٍ وَأَصْحَابُ الرَّأْيِ: الْآيَةُ نَزَلَتْ فِيمَنْ خَرَجَ مِنَ الْمُسْلِمِينَ يَقْطَعُ السَّبِيلَ وَيَسْعَى فِي الْأَرْضِ بِالْفَسَادِ.","w":"القرطبي","en":"Al-Qurtubi: Malik, al-Shafi'i, Abu Thawr and the people of opinion said the verse was revealed about Muslims who go out cutting the road and spreading corruption on earth."}]},{"id":"muharram","ch":"at3ima","t":"المطعومات المحرَّمة","e":"الميتة والدم ولحم الخنزير وما أُهل لغير الله به والمنخنقة وما بعدها.","ay":[[5,3,3],[6,145,145]],"q":[{"bk":"saadi","s":5,"ay":3,"x":"واعلم أن الله تبارك وتعالى لا يحرِّم ما يحرِّم إلاَّ صيانةً لعباده وحمايةً لهم من الضرر الموجود في المحرَّمات، وقد يبين للعبادِ ذلك وقد لا يبين، فأخبر أنه حرَّم {الميتة}، والمراد بالميتة ما فُقدت حياته بغير ذكاة شرعيَّة؛ فإنَّها تحرُم لضررها، وهو احتقان الدم في جوفها ولحمها المضرِّ بآكلها، وكثيراً ما تموت بعلةٍ تكون سبباً لهلاكها فتضرُّ بالآكل، ويستثنى من ذلك مَيْتَةُ الجراد والسمك؛ فإنه حلال، {والدَّمُ}؛ أي: المسفوح؛ كما قُيِّدَ في الآية الأخرى، {ولحمُ الخنزير}: وذلك شامل لجميع أجزائِهِ، وإنما نصَّ الله عليه من بين سائر الخبائث من السباع؛ لأنَّ طائفة من أهل الكتاب من النصارى يزعمون أن الله أحلَّه لهم؛ أي: فلا تغترُّوا بهم، بل هو محرَّم من جملة الخبائث، {وما أُهِلَّ لغيرِ الله به}؛ أي …","w":"السعدي","en":"Al-Sa'di: Allah forbids only to protect His servants from harm, whether or not it is explained; carrion means what died without lawful slaughter; blood means flowing blood; pork includes all its parts; and locusts and fish are excepted from carrion."},{"bk":"qurtubi","s":5,"ay":3,"x":"وَمَالِكٌ وَغَيْرُهُ اعْتَبَرُوا الْمَوْتَ عَلَى وَجْهٍ يَطِيبُ مَعَهُ اللَّحْمُ، وَيَفْتَرِقُ فِيهِ الْحَلَالُ- وَهُوَ اللَّحْمُ- مِنَ الْحَرَامِ الَّذِي يَخْرُجُ بِقَطْعِ الْأَوْدَاجِ وَهُوَ مَذْهَبُ أَبِي حَنِيفَةَ، وَعَلَيْهِ يَدُلُّ حَدِيثُ رَافِعِ بْنِ خَدِيجٍ فِي قَوْلِهِ: (مَا أَنْهَرَ الدَّمَ).","w":"القرطبي","en":"Al-Qurtubi: Malik and others considered the manner of death that makes the meat good and distinguishes the lawful meat from the forbidden by cutting the throat vessels, which is also Abu Hanifa's school; the hadith of Rafi' ibn Khadij is evidence: \"whatever makes the blood flow\"."}]},{"id":"dhakat","ch":"at3ima","t":"الذبائح وذكر اسم الله","e":"النهي عن الأكل مما لم يذكر اسم الله عليه.","ay":[[6,121,121],[6,118,119]],"q":[{"bk":"saadi","s":6,"ay":121,"x":"ويدخل تحت هذا المنهي عنه ما ذُكِرَ عليه اسم غير الله؛ كالذي يُذبح للأصنام وآلهة المشركين ؛ فإنَّ هذا مما أُهلَّ لغير الله به المحرَّم بالنصِّ عليه خصوصاً. ويدخل في ذلك متروك التسمية مما ذبح لله كالضحايا والهدايا، أو للحم والأكل، إذا كان الذابح متعمِّداً ترك التسمية عند كثير من العلماء، ويخرج من هذا العموم الناسي بالنصوص الأخر الدالة على رفع الحرج عنه.","w":"السعدي","en":"Al-Sa'di: the prohibition includes what was slaughtered in the name of other than Allah, such as for idols; and includes what was slaughtered for Allah but deliberately without mentioning His name, according to many scholars, while the forgetful is excused by other texts."},{"bk":"qurtubi","s":6,"ay":121,"x":"فَإِنْ تَرَكَهَا عَمْدًا لَمْ يُؤْكَلَا، وقال فِي الْكِتَابِ مَالِكٌ وَابْنُ الْقَاسِمِ، وَهُوَ قَوْلُ أَبِي حَنِيفَةَ وَأَصْحَابِهِ وَالثَّوْرِيِّ وَالْحَسَنِ بْنِ حَيٍّ وَعِيسَى وَأَصْبَغَ، وَقَالَهُ سَعِيدُ بْنُ جُبَيْرٍ وَعَطَاءٌ، وَاخْتَارَهُ النَّحَّاسُ وَقَالَ: هَذَا أَحْسَنُ، لِأَنَّهُ لَا يُسَمَّى فَاسِقًا إِذَا كَانَ نَاسِيًا.","w":"القرطبي","en":"Al-Qurtubi: if one deliberately omitted the name, the animal is not eaten; this was said by Malik and Ibn al-Qasim, Abu Hanifa and his companions, al-Thawri and others; al-Nahhas chose it, saying it is best because one who forgot is not called a transgressor."}]},{"id":"sayd","ch":"at3ima","t":"الصيد بالجوارح","e":"إباحة الطيبات وما أمسكت الجوارح المعلَّمة وذكر اسم الله عليه.","ay":[[5,4,4]],"q":[{"bk":"saadi","s":5,"ay":4,"x":"الثاني: أنه يشترط أن تكون معلَّمة بما يُعَدُّ في العرف تعليماً؛ بأن يسترسل إذا أرسل، وينزجر إذا زجر، وإذا أمسك لم يأكل، ولهذا قال:{تعلِّمونهن مما علَّمكم الله فكلوا مما أمۡسَكۡنَ عليكم}؛ أي: أمسكن من الصيد لأجلكم، وما أكل منه الجارح؛ فإنَّه لا يعلم أنه أمسكه على صاحبه، ولعلَّه أن يكون أمسكه على نفسه. الثالث: اشتراط أن يجرحه الكلب أو الطير ونحوهما؛ لقوله:{من الجوارح}؛ مع ما تقدم من تحريم المنخنقة؛ فلو خنقه الكلب أو غيره أو قتله بثقله؛ لم يُبَحْ، هذا بناء على أن الجوارح اللاتي يجرحن الصيد بأنيابها أو مخالبها، والمشهور أن الجوارح بمعنى الكواسب؛ أي: المحصِّلات للصيد والمدركات له، فلا يكون فيها على هذا دلالة.","w":"السعدي","en":"Al-Sa'di: the hunting animal must be trained as customarily understood: it goes when sent, stops when called, and does not eat what it catches, as it may have caught it for itself; and it must wound the prey; if it strangled the animal or killed it by weight, it is not lawful."},{"bk":"qurtubi","s":5,"ay":4,"x":"وَقَدْ شَرَطَ الشَّافِعِيُّ وَجُمْهُورٌ مِنَ الْعُلَمَاءِ فِي التَّعْلِيمِ أَنْ يُمْسِكَ عَلَى صَاحِبِهِ، وَلَمْ يَشْتَرِطْهُ مَالِكٌ فِي الْمَشْهُورِ عَنْهُ.","w":"القرطبي","en":"Al-Qurtubi: al-Shafi'i and a majority of scholars required, as part of the training, that the animal holds the catch for its owner, while Malik, in the well-known report, did not require it."}]},{"id":"kitab","ch":"at3ima","t":"طعام أهل الكتاب ونكاح المحصنات منهم","e":"حلّ طعام الذين أوتوا الكتاب والمحصنات من نسائهم.","ay":[[5,5,5]],"q":[{"bk":"saadi","s":5,"ay":5,"x":"والدليل على أن المراد بطعامهم ذبائحهم: أنَّ الطعام الذي ليس من الذبائح؛ كالحبوب والثمارِ، ليس لأهل الكتاب فيه خصوصيَّةٌ، بل يُباح ذلك، ولو كان من طعام غيرهم. وأيضاً؛ فإنه أضاف الطعام إليهم، فدل ذلك على أنه كان طعاماً بسبب ذبحهم، ولا يقال: إنَّ ذلك للتمليك، وإنَّ المراد الطعام الذي يملكون؛ لأنَّ هذا لا يُباح على وجه الغصب ولا من المسلمين.","w":"السعدي","en":"Al-Sa'di: the evidence that \"their food\" means their slaughtered meat is that other foods, like grain and fruit, have no special ruling for the People of the Book and are lawful even from others; and the food is attributed to them because it is food by their slaughter."}]},{"id":"khamr","ch":"at3ima","t":"تحريم الخمر والميسر","e":"الخمر والميسر والأنصاب والأزلام رجس من عمل الشيطان وأمر باجتنابها.","ay":[[5,90,91]],"q":[{"bk":"saadi","s":5,"ay":90,"x":"يذمُّ تعالى هذه الأشياء القبيحة، ويخبر أنها من عمل الشيطان، وأنها رجس؛ {فاجتنبوه}؛ أي: اتركوه، {لعلَّكم تفلحون}؛ فإنَّ الفلاح لا يتمُّ إلاَّ بترك ما حرَّم الله، خصوصاً هذه الفواحش المذكورة، وهي الخمر، وهو كلُّ ما خامر العقل؛ أي: غطاه بسكره، والميسر، وهو جميع المغالَبات التي فيها عوض من الجانبين؛ كالمراهنة ونحوها، والأنصاب، وهي الأصنام والأنداد ونحوها مما يُنصب ويُعبد من دون الله، والأزلام التي [يستقسمون] بها. فهذه الأربعة نهى الله عنها، وزجر، وأخبر عن مفاسدها الداعية إلى تركها واجتنابها: فمنها: أنها رجسٌ؛ أي: نجس خبث معنى، وإن لم تكن نجسة حِسًّا، والأمور الخبيثة مما ينبغي اجتنابها وعدم التدنُّس بأوضارها.","w":"السعدي","en":"Al-Sa'di: Allah condemns these things, calling them filth and Satan's work, and commands avoiding them for success; khamr is whatever clouds the mind, maysir is every contest with stakes from both sides, ansab are idols, and azlam are divining arrows; they are filth in meaning even if not physically impure."},{"bk":"qurtubi","s":5,"ay":90,"x":"الثَّامِنَةُ- أَجْمَعَ الْمُسْلِمُونَ عَلَى تَحْرِيمِ بَيْعِ الْخَمْرِ وَالدَّمِ، وَفِي ذَلِكَ دَلِيلٌ عَلَى تَحْرِيمِ بَيْعِ الْعَذِرَاتِ وَسَائِرِ النَّجَاسَاتِ وَمَا لَا يَحِلُّ أَكْلُهُ، وَلِذَلِكَ- وَاللَّهُ أَعْلَمُ- كَرِهَ مَالِكٌ بَيْعَ زِبْلِ الدَّوَابِّ، وَرَخَّصَ فِيهِ ابْنُ الْقَاسِمِ لِمَا فِيهِ مِنَ الْمَنْفَعَةِ، وَالْقِيَاسُ مَا قَالَهُ مَالِكٌ، وَهُوَ مَذْهَبُ الشَّافِعِيِّ، وهذا الحديث شاهد بصحة ذلك.","w":"القرطبي","en":"Al-Qurtubi: Muslims agreed that selling khamr and blood is forbidden, which indicates the prohibition of selling excrement and all impure things that may not be eaten; hence Malik disliked selling animal dung, while Ibn al-Qasim allowed it for its benefit; the analogy is Malik's, and al-Shafi'i's school."}]},{"id":"yamin","ch":"siyasa","t":"كفارة اليمين","e":"عدم المؤاخذة باللغو في الأيمان، وكفارة اليمين المعقودة.","ay":[[5,89,89]],"q":[{"bk":"saadi","s":5,"ay":89,"x":"أي: في أيمانكم التي صدرت على وجه اللغو، وهي الأيمان التي حلف بها المقسم من غير نيَّة ولا قصدٍ، أو عقدها يظنُّ صدقَ نفسه، فبان بخلاف ذلك، {ولكن يؤاخذكم بما عقَّدتم الأيمان}؛ أي: بما عزمتم عليه وعقدت عليه قلوبكم؛ كما قال في الآية الأخرى:{ولكن يؤاخِذُكُم بما كَسَبَتۡ قلوبُكم}، {فكفَّارتُهُ}؛ أي: كفارة اليمين الذي عقدتموها بقصدكم: {إطعام عشرة مساكين}، وذلك الإطعام {من أوسط ما تُطۡعِمون أهليكم أو كسوتهم}؛ أي: كسوة عشرة مساكين، والكسوة هي التي تجزي في الصلاة، {أو تحرير رقبة}؛ [أي: عتق رقبة] مؤمنةٍ؛ كما قُيِّدت في غير هذا الموضع؛ فمتى فعل واحداً من هذه الثلاثة؛ فقد انحلَّت يمينه.","w":"السعدي","en":"Al-Sa'di: Allah does not hold you to thoughtless oaths, sworn without intention or in the belief one was truthful, but to oaths you resolved in your hearts; expiation is feeding ten poor people from the average of what you feed your families, or clothing them, or freeing a believing slave."},{"bk":"qurtubi","s":5,"ay":89,"x":"الثَّالِثَةُ وَالْعِشْرُونَ- الْإِطْعَامُ عِنْدَ مَالِكٍ مُدٌّ لِكُلِّ وَاحِدٍ مِنَ الْمَسَاكِينِ الْعَشَرَةِ، إِنْ كَانَ بِمَدِينَةِ النَّبِيِّ ﷺ، وَبِهِ قَالَ الشَّافِعِيُّ وَأَهْلُ الْمَدِينَةِ.","w":"القرطبي","en":"Al-Qurtubi: feeding, for Malik, is one mudd for each of the ten poor people if in the Prophet's city, and so said al-Shafi'i and the people of Madina."}]},{"id":"adl","ch":"siyasa","t":"الأمانات والحكم بالعدل","e":"أداء الأمانات إلى أهلها والحكم بين الناس بالعدل.","ay":[[4,58,58]],"q":[{"bk":"saadi","s":4,"ay":58,"x":"الأمانات كلُّ ما اؤتُمِنَ عليه الإنسان وأُمِرَ بالقيام به، فأمر اللهُ عباده بأدائِها؛ أي: كاملة موفَّرة لا منقوصة ولا مبخوسةً ولا ممطولاً بها، ويدخُلُ في ذلك أماناتُ الولايات والأموال والأسرار والمأمورات التي لا يطَّلع عليها إلا الله. … والمراد بالعدل الذي أمر الله بالحكم به هو ما شَرَعَهُ الله على لسان رسولِهِ من الحدود والأحكام، وهذا يستلزم معرفة العدل ليحكُمَ به، ولما كانت هذه أوامر حسنةً عادلةً؛ قال:{إنَّ الله نِعمَّا يَعِظُكُم به، إنَّ اللهَ كان سميعاً بصيراً}: وهذا مدحٌ من الله لأوامره ونواهيه؛ لاشتمالها على مصالح الدارين ودفع مضارِّهما؛ لأنَّ شارعها السميع البصير الذي لا تَخْفى عليه خافيةٌ ويعلم من مصالح العباد ما لا يعلمون.","w":"السعدي","en":"Al-Sa'di: trusts are all that a person is entrusted with and commanded to uphold; Allah commands returning them complete, which includes offices, wealth and secrets; and the justice commanded in judging is what Allah legislated through His Messenger, which requires knowing it."}]},{"id":"bughat","ch":"siyasa","t":"قتال البغاة والإصلاح بين الفئتين","e":"قتال الفئة الباغية حتى تفيء، ثم الإصلاح بين الطائفتين بالعدل.","ay":[[49,9,10]],"q":[{"bk":"saadi","s":49,"ay":9,"x":"؛ أي: ترجع إلى ما حدَّ الله ورسولُه من فعل الخير وترك الشرِّ الذي من أعظمه الاقتتال. وقولُه:{فإن فاءتۡ فأصۡلِحوا بينَهما بالعَدۡلِ}: هذا أمرٌ بالصُّلح وبالعدل في الصلح؛ فإنَّ الصُّلح قد يوجد، ولكن لا يكون بالعدل، بل بالظُّلم والحيف على أحد الخصمين؛ فهذا ليس هو الصُّلح المأمورُ به، فيجب أن لا يراعَى أحدهما لقرابةٍ أو وطنٍ أو غير ذلك من المقاصد والأغراض، التي توجب العدول عن العدل.","w":"السعدي","en":"Al-Sa'di: if one party oppresses the other, fight the oppressor until it returns to Allah's command; if it returns, reconcile between them with justice, not siding with either because of kinship or homeland, since a reconciliation that wrongs one side is not the commanded one."}]},{"id":"aman","ch":"siyasa","t":"الأمان وإجارة من طلب سماع الحق","e":"إجارة المشرك المستجير ليسمع كلام الله ثم إبلاغه مأمنه.","ay":[[9,6,6]],"q":[{"bk":"saadi","s":9,"ay":6,"x":"لما كان ما تقدَّم من قوله: {فإذا انسلخ الأشهرُ الحُرُم فاقتُلوا المشركين حيث وجدتموهم وخُذوهم واحصُروهم واقعُدوا لهم كلَّ مرصد}: أمراً عامًّا في جميع الأحوال وفي كلِّ الأشخاص منهم؛ ذكر تعالى أن المصلحة إذا اقتضت تقريب بعضهم؛ جاز، بل وجب ذلك، فقال:{وإنۡ أحدٌ من المشركين استجارَكَ}؛ أي: طلب منك أن تجيره وتمنعه من الضَّرر لأجل أن يسمع كلام الله وينظر حالة الإسلام، {فأجِرۡه حتَّى يسمعَ كلام الله}: ثم إنْ أسلم؛ فذاك، وإلاَّ؛ فأبلِغْه مأمَنَه؛ أي: المحل الذي يأمن فيه. والسبب في ذلك أن الكفار قومٌ لا يعلمون؛ فربَّما كان استمرارُهم على كفرهم لجهل منهم إذا زال اختاروا عليه الإسلام؛ فلذلك أمر الله رسوله.","w":"السعدي","en":"Al-Sa'di: after the general command against the idolaters, Allah mentions that when interest requires drawing some of them near, it is permitted and even required: give protection to one who asks so he may hear Allah's words and see Islam, then escort him to safety if he does not accept."}]},{"id":"ghadd","ch":"siyasa","t":"غضّ البصر وحفظ الفرج","e":"غض الأبصار وحفظ الفروج للمؤمنين والمؤمنات وما يُبدى من الزينة.","ay":[[24,30,31]],"q":[{"bk":"saadi","s":24,"ay":30,"x":"أي: أرشدِ المؤمنين وقُلْ لهم: الذين معهم إيمانٌ يمنعُهم من وقوع ما يُخِلُّ بالإيمان {يغضُّوا من أبصارِهم}: عن النظر إلى العورات وإلى النساء الأجنبيَّات وإلى المُرْدانِ، الذين يُخاف بالنظرِ إليهم الفتنة وإلى زينة الدُّنيا التي تفتنُ وتوقِعُ في المحذور. {ويحفَظُوا فروجَهم}: عن الوطء الحرام في قُبُل أو دُبُر أو ما دونَ ذلك وعن التمكين من مسِّها والنظر إليها. … وتأمَّل كيف أمر بحفظِ الفرج مطلقاً لأنَّه لا يُباح في حالةٍ من الأحوال، وأما البصرُ؛ فقال:{يَغُضُّوا مِنۡ أبصارِهم}: أتى بأداة مِنْ الدالَّة على التبعيض؛ فإنَّه يجوز النظر في بعض الأحوال لحاجةٍ؛ كنظر الشاهدِ والمعامل والخاطبِ ونحو ذلك.","w":"السعدي","en":"Al-Sa'di: lower the gaze from nakedness, unrelated women and tempting things; guard chastity from forbidden relations and from allowing touch or sight; Allah commands guarding chastity absolutely since it is never lawful, but lowering the gaze only \"some\" since looking is allowed in some cases of need, such as for witnesses, buyers and a suitor."}]},{"id":"hijab","ch":"siyasa","t":"الحجاب والجلابيب","e":"إدناء الجلابيب وضرب الخُمُر على الجيوب، وما ظهر من الزينة.","ay":[[33,59,59],[24,31,31]],"q":[{"bk":"saadi","s":33,"ay":59,"x":"هذه الآية هي التي تسمَّى آية الحجاب، فأمر الله نبيَّه أن يأمُرَ النساء عموماً، ويبدأ بزوجاتِهِ وبناتِهِ ـ لأنَّهنَّ آكدُ من غيرهنَّ، ولأنَّ الآمر لغيره ينبغي أن يبدأ بأهله قبل غيرهم؛ كما قال تعالى:{يا أيُّها الذين آمنوا قُوا أنفسَكم وأهليكم ناراً}. {أن يُدۡنينَ عليهنَّ من جلابيبِهنَّ}: وهنَّ اللاَّتي يَكُنَّ فوق الثياب من ملحفةٍ وخمارٍ ورداءٍ ونحوه؛ أي: يغطِّين بها وجوهَهن وصدورَهن، ثم ذكر حكمة ذلك، فقال:{ذلك أدنى أن يُعۡرَفۡنَ فلا يُؤۡذَيۡنَ}: دلَّ على وجود أذيَّةٍ إن لم يحتَجِبْن، وذلك لأنهنَّ إذا لم يحتجِبْن، ربَّما ظنَّ أنهنَّ غير عفيفاتٍ، فيتعرَّض لَهُنَّ مَنْ في قلبهِ مرضٌ، فيؤذيهنَّ، وربما استُهين بهنَّ، وظُنَّ أنهنَّ إماء، فتهاون بهنَّ من يريدُ الشرَّ؛ فالاحتجابُ حاسمٌ لمطامع الطامعين فيهنَّ.","w":"السعدي","en":"Al-Sa'di: this is the verse of hijab; the Prophet is to command women, beginning with his wives and daughters, to draw their outer garments close, covering faces and chests, \"that they may be known and not harassed\", since uncovering invites the ill-intentioned."},{"bk":"qurtubi","s":24,"ay":31,"x":"قَالَ ابْنُ عَطِيَّةَ: وَيَظْهَرُ لِي بِحُكْمِ أَلْفَاظِ الْآيَةِ أَنَّ الْمَرْأَةَ مَأْمُورَةٌ بِأَلَّا تُبْدِيَ وَأَنْ تَجْتَهِدَ فِي الْإِخْفَاءِ لِكُلِّ مَا هُوَ زِينَةٌ، وَوَقَعَ الِاسْتِثْنَاءُ فِيمَا يَظْهَرُ بِحُكْمِ ضَرُورَةِ حَرَكَةٍ فِيمَا لَا بُدَّ مِنْهُ، أَوْ إِصْلَاحِ شَأْنٍ وَنَحْوِ ذَلِكَ. فَ\"- مَا ظَهَرَ \"عَلَى هَذَا الْوَجْهِ مِمَّا تُؤَدِّي إِلَيْهِ الضَّرُورَةُ فِي النِّسَاءِ فَهُوَ الْمَعْفُوُّ عَنْهُ. قُلْتُ: هَذَا قَوْلٌ حَسَنٌ، إِلَّا أَنَّهُ لَمَّا كَانَ الْغَالِبُ مِنَ الْوَجْهِ وَالْكَفَّيْنِ ظُهُورُهُمَا عَادَةً وَعِبَادَةً وَذَلِكَ فِي الصَّلَاةِ وَالْحَجِّ، فَيَصْلُحُ أَنْ يَكُونَ الِاسْتِثْنَاءُ رَاجِعًا إِلَيْهِمَا.","w":"القرطبي","en":"Ibn Atiyya in al-Qurtubi: women are commanded not to show adornment and to strive to conceal it, with the exception only of what appears by necessity of movement; and al-Qurtubi adds that since the face and hands usually appear in custom and worship, in prayer and Hajj, the exception can refer to them."}]}],"ay":{"150":"قَدۡ نَرَىٰ تَقَلُّبَ وَجۡهِكَ فِي ٱلسَّمَآءِۖ فَلَنُوَلِّيَنَّكَ قِبۡلَةٗ تَرۡضَىٰهَاۚ فَوَلِّ وَجۡهَكَ شَطۡرَ ٱلۡمَسۡجِدِ ٱلۡحَرَامِۚ وَحَيۡثُ مَا كُنتُمۡ فَوَلُّواْ وُجُوهَكُمۡ شَطۡرَهُۥۗ وَإِنَّ ٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ لَيَعۡلَمُونَ أَنَّهُ ٱلۡحَقُّ مِن رَّبِّهِمۡۗ وَمَا ٱللَّهُ بِغَٰفِلٍ عَمَّا يَعۡمَلُونَ","184":"يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ كُتِبَ عَلَيۡكُمُ ٱلۡقِصَاصُ فِي ٱلۡقَتۡلَىۖ ٱلۡحُرُّ بِٱلۡحُرِّ وَٱلۡعَبۡدُ بِٱلۡعَبۡدِ وَٱلۡأُنثَىٰ بِٱلۡأُنثَىٰۚ فَمَنۡ عُفِيَ لَهُۥ مِنۡ أَخِيهِ شَيۡءٞ فَٱتِّبَاعُۢ بِٱلۡمَعۡرُوفِ وَأَدَآءٌ إِلَيۡهِ بِإِحۡسَٰنٖۗ ذَٰلِكَ تَخۡفِيفٞ مِّن رَّبِّكُمۡ وَرَحۡمَةٞۗ فَمَنِ ٱعۡتَدَىٰ بَعۡدَ ذَٰلِكَ فَلَهُۥ عَذَابٌ أَلِيمٞ","185":"وَلَكُمۡ فِي ٱلۡقِصَاصِ حَيَوٰةٞ يَٰٓأُوْلِي ٱلۡأَلۡبَٰبِ لَعَلَّكُمۡ تَتَّقُونَ","186":"كُتِبَ عَلَيۡكُمۡ إِذَا حَضَرَ أَحَدَكُمُ ٱلۡمَوۡتُ إِن تَرَكَ خَيۡرًا ٱلۡوَصِيَّةُ لِلۡوَٰلِدَيۡنِ وَٱلۡأَقۡرَبِينَ بِٱلۡمَعۡرُوفِۖ حَقًّا عَلَى ٱلۡمُتَّقِينَ","187":"فَمَنۢ بَدَّلَهُۥ بَعۡدَ مَا سَمِعَهُۥ فَإِنَّمَآ إِثۡمُهُۥ عَلَى ٱلَّذِينَ يُبَدِّلُونَهُۥٓۚ إِنَّ ٱللَّهَ سَمِيعٌ عَلِيمٞ","188":"فَمَنۡ خَافَ مِن مُّوصٖ جَنَفًا أَوۡ إِثۡمٗا فَأَصۡلَحَ بَيۡنَهُمۡ فَلَآ إِثۡمَ عَلَيۡهِۚ إِنَّ ٱللَّهَ غَفُورٞ رَّحِيمٞ","194":"وَلَا تَأۡكُلُوٓاْ أَمۡوَٰلَكُم بَيۡنَكُم بِٱلۡبَٰطِلِ وَتُدۡلُواْ بِهَآ إِلَى ٱلۡحُكَّامِ لِتَأۡكُلُواْ فَرِيقٗا مِّنۡ أَمۡوَٰلِ ٱلنَّاسِ بِٱلۡإِثۡمِ وَأَنتُمۡ تَعۡلَمُونَ","228":"وَيَسۡـَٔلُونَكَ عَنِ ٱلۡمَحِيضِۖ قُلۡ هُوَ أَذٗى فَٱعۡتَزِلُواْ ٱلنِّسَآءَ فِي ٱلۡمَحِيضِ وَلَا تَقۡرَبُوهُنَّ حَتَّىٰ يَطۡهُرۡنَۖ فَإِذَا تَطَهَّرۡنَ فَأۡتُوهُنَّ مِنۡ حَيۡثُ أَمَرَكُمُ ٱللَّهُۚ إِنَّ ٱللَّهَ يُحِبُّ ٱلتَّوَّٰبِينَ وَيُحِبُّ ٱلۡمُتَطَهِّرِينَ","232":"لِّلَّذِينَ يُؤۡلُونَ مِن نِّسَآئِهِمۡ تَرَبُّصُ أَرۡبَعَةِ أَشۡهُرٖۖ فَإِن فَآءُو فَإِنَّ ٱللَّهَ غَفُورٞ رَّحِيمٞ","233":"وَإِنۡ عَزَمُواْ ٱلطَّلَٰقَ فَإِنَّ ٱللَّهَ سَمِيعٌ عَلِيمٞ","234":"وَٱلۡمُطَلَّقَٰتُ يَتَرَبَّصۡنَ بِأَنفُسِهِنَّ ثَلَٰثَةَ قُرُوٓءٖۚ وَلَا يَحِلُّ لَهُنَّ أَن يَكۡتُمۡنَ مَا خَلَقَ ٱللَّهُ فِيٓ أَرۡحَامِهِنَّ إِن كُنَّ يُؤۡمِنَّ بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِۚ وَبُعُولَتُهُنَّ أَحَقُّ بِرَدِّهِنَّ فِي ذَٰلِكَ إِنۡ أَرَادُوٓاْ إِصۡلَٰحٗاۚ وَلَهُنَّ مِثۡلُ ٱلَّذِي عَلَيۡهِنَّ بِٱلۡمَعۡرُوفِۚ وَلِلرِّجَالِ عَلَيۡهِنَّ دَرَجَةٞۗ وَٱللَّهُ عَزِيزٌ حَكِيمٌ","235":"ٱلطَّلَٰقُ مَرَّتَانِۖ فَإِمۡسَاكُۢ بِمَعۡرُوفٍ أَوۡ تَسۡرِيحُۢ بِإِحۡسَٰنٖۗ وَلَا يَحِلُّ لَكُمۡ أَن تَأۡخُذُواْ مِمَّآ ءَاتَيۡتُمُوهُنَّ شَيۡـًٔا إِلَّآ أَن يَخَافَآ أَلَّا يُقِيمَا حُدُودَ ٱللَّهِۖ فَإِنۡ خِفۡتُمۡ أَلَّا يُقِيمَا حُدُودَ ٱللَّهِ فَلَا جُنَاحَ عَلَيۡهِمَا فِيمَا ٱفۡتَدَتۡ بِهِۦۗ تِلۡكَ حُدُودُ ٱللَّهِ فَلَا تَعۡتَدُوهَاۚ وَمَن يَتَعَدَّ حُدُودَ ٱللَّهِ فَأُوْلَٰٓئِكَ هُمُ ٱلظَّٰلِمُونَ","236":"فَإِن طَلَّقَهَا فَلَا تَحِلُّ لَهُۥ مِنۢ بَعۡدُ حَتَّىٰ تَنكِحَ زَوۡجًا غَيۡرَهُۥۗ فَإِن طَلَّقَهَا فَلَا جُنَاحَ عَلَيۡهِمَآ أَن يَتَرَاجَعَآ إِن ظَنَّآ أَن يُقِيمَا حُدُودَ ٱللَّهِۗ وَتِلۡكَ حُدُودُ ٱللَّهِ يُبَيِّنُهَا لِقَوۡمٖ يَعۡلَمُونَ","239":"۞ وَٱلۡوَٰلِدَٰتُ يُرۡضِعۡنَ أَوۡلَٰدَهُنَّ حَوۡلَيۡنِ كَامِلَيۡنِۖ لِمَنۡ أَرَادَ أَن يُتِمَّ ٱلرَّضَاعَةَۚ وَعَلَى ٱلۡمَوۡلُودِ لَهُۥ رِزۡقُهُنَّ وَكِسۡوَتُهُنَّ بِٱلۡمَعۡرُوفِۚ لَا تُكَلَّفُ نَفۡسٌ إِلَّا وُسۡعَهَاۚ لَا تُضَآرَّ وَٰلِدَةُۢ بِوَلَدِهَا وَلَا مَوۡلُودٞ لَّهُۥ بِوَلَدِهِۦۚ وَعَلَى ٱلۡوَارِثِ مِثۡلُ ذَٰلِكَۗ فَإِنۡ أَرَادَا فِصَالًا عَن تَرَاضٖ مِّنۡهُمَا وَتَشَاوُرٖ فَلَا جُنَاحَ عَلَيۡهِمَاۗ وَإِنۡ أَرَدتُّمۡ أَن تَسۡتَرۡضِعُوٓاْ أَوۡلَٰدَكُمۡ فَلَا جُنَاحَ عَلَيۡكُمۡ إِذَا سَلَّمۡتُم مَّآ ءَاتَيۡتُم بِٱلۡمَعۡرُوفِۗ وَٱتَّقُواْ ٱللَّهَ وَٱعۡلَمُوٓاْ أَنَّ ٱللَّهَ بِمَا تَعۡمَلُونَ بَصِيرٞ","240":"وَٱلَّذِينَ يُتَوَفَّوۡنَ مِنكُمۡ وَيَذَرُونَ أَزۡوَٰجٗا يَتَرَبَّصۡنَ بِأَنفُسِهِنَّ أَرۡبَعَةَ أَشۡهُرٖ وَعَشۡرٗاۖ فَإِذَا بَلَغۡنَ أَجَلَهُنَّ فَلَا جُنَاحَ عَلَيۡكُمۡ فِيمَا فَعَلۡنَ فِيٓ أَنفُسِهِنَّ بِٱلۡمَعۡرُوفِۗ وَٱللَّهُ بِمَا تَعۡمَلُونَ خَبِيرٞ","281":"ٱلَّذِينَ يَأۡكُلُونَ ٱلرِّبَوٰاْ لَا يَقُومُونَ إِلَّا كَمَا يَقُومُ ٱلَّذِي يَتَخَبَّطُهُ ٱلشَّيۡطَٰنُ مِنَ ٱلۡمَسِّۚ ذَٰلِكَ بِأَنَّهُمۡ قَالُوٓاْ إِنَّمَا ٱلۡبَيۡعُ مِثۡلُ ٱلرِّبَوٰاْۗ وَأَحَلَّ ٱللَّهُ ٱلۡبَيۡعَ وَحَرَّمَ ٱلرِّبَوٰاْۚ فَمَن جَآءَهُۥ مَوۡعِظَةٞ مِّن رَّبِّهِۦ فَٱنتَهَىٰ فَلَهُۥ مَا سَلَفَ وَأَمۡرُهُۥٓ إِلَى ٱللَّهِۖ وَمَنۡ عَادَ فَأُوْلَٰٓئِكَ أَصۡحَٰبُ ٱلنَّارِۖ هُمۡ فِيهَا خَٰلِدُونَ","282":"يَمۡحَقُ ٱللَّهُ ٱلرِّبَوٰاْ وَيُرۡبِي ٱلصَّدَقَٰتِۗ وَٱللَّهُ لَا يُحِبُّ كُلَّ كَفَّارٍ أَثِيمٍ","284":"يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ ٱتَّقُواْ ٱللَّهَ وَذَرُواْ مَا بَقِيَ مِنَ ٱلرِّبَوٰٓاْ إِن كُنتُم مُّؤۡمِنِينَ","285":"فَإِن لَّمۡ تَفۡعَلُواْ فَأۡذَنُواْ بِحَرۡبٖ مِّنَ ٱللَّهِ وَرَسُولِهِۦۖ وَإِن تُبۡتُمۡ فَلَكُمۡ رُءُوسُ أَمۡوَٰلِكُمۡ لَا تَظۡلِمُونَ وَلَا تُظۡلَمُونَ","286":"وَإِن كَانَ ذُو عُسۡرَةٖ فَنَظِرَةٌ إِلَىٰ مَيۡسَرَةٖۚ وَأَن تَصَدَّقُواْ خَيۡرٞ لَّكُمۡ إِن كُنتُمۡ تَعۡلَمُونَ","288":"يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ إِذَا تَدَايَنتُم بِدَيۡنٍ إِلَىٰٓ أَجَلٖ مُّسَمّٗى فَٱكۡتُبُوهُۚ وَلۡيَكۡتُب بَّيۡنَكُمۡ كَاتِبُۢ بِٱلۡعَدۡلِۚ وَلَا يَأۡبَ كَاتِبٌ أَن يَكۡتُبَ كَمَا عَلَّمَهُ ٱللَّهُۚ فَلۡيَكۡتُبۡ وَلۡيُمۡلِلِ ٱلَّذِي عَلَيۡهِ ٱلۡحَقُّ وَلۡيَتَّقِ ٱللَّهَ رَبَّهُۥ وَلَا يَبۡخَسۡ مِنۡهُ شَيۡـٔٗاۚ فَإِن كَانَ ٱلَّذِي عَلَيۡهِ ٱلۡحَقُّ سَفِيهًا أَوۡ ضَعِيفًا أَوۡ لَا يَسۡتَطِيعُ أَن يُمِلَّ هُوَ فَلۡيُمۡلِلۡ وَلِيُّهُۥ بِٱلۡعَدۡلِۚ وَٱسۡتَشۡهِدُواْ شَهِيدَيۡنِ مِن رِّجَالِكُمۡۖ فَإِن لَّمۡ يَكُونَا رَجُلَيۡنِ فَرَجُلٞ وَٱمۡرَأَتَانِ مِمَّن تَرۡضَوۡنَ مِنَ ٱلشُّهَدَآءِ أَن تَضِلَّ إِحۡدَىٰهُمَا فَتُذَكِّرَ إِحۡدَىٰهُمَا ٱلۡأُخۡرَىٰۚ وَلَا يَأۡبَ ٱلشُّهَدَآءُ إِذَا مَا دُعُواْۚ وَلَا تَسۡـَٔمُوٓاْ أَن تَكۡتُبُوهُ صَغِيرًا أَوۡ كَبِيرًا إِلَىٰٓ أَجَلِهِۦۚ ذَٰلِكُمۡ أَقۡسَطُ عِندَ ٱللَّهِ وَأَقۡوَمُ لِلشَّهَٰدَةِ وَأَدۡنَىٰٓ أَلَّا تَرۡتَابُوٓاْ إِلَّآ أَن تَكُونَ تِجَٰرَةً حَاضِرَةٗ تُدِيرُونَهَا بَيۡنَكُمۡ فَلَيۡسَ عَلَيۡكُمۡ جُنَاحٌ أَلَّا تَكۡتُبُوهَاۗ وَأَشۡهِدُوٓاْ إِذَا تَبَايَعۡتُمۡۚ وَلَا يُضَآرَّ كَاتِبٞ وَلَا شَهِيدٞۚ وَإِن تَفۡعَلُواْ فَإِنَّهُۥ فُسُوقُۢ بِكُمۡۗ وَٱتَّقُواْ ٱللَّهَۖ وَيُعَلِّمُكُمُ ٱللَّهُۗ وَٱللَّهُ بِكُلِّ شَيۡءٍ عَلِيمٞ","289":"۞ وَإِن كُنتُمۡ عَلَىٰ سَفَرٖ وَلَمۡ تَجِدُواْ كَاتِبٗا فَرِهَٰنٞ مَّقۡبُوضَةٞۖ فَإِنۡ أَمِنَ بَعۡضُكُم بَعۡضٗا فَلۡيُؤَدِّ ٱلَّذِي ٱؤۡتُمِنَ أَمَٰنَتَهُۥ وَلۡيَتَّقِ ٱللَّهَ رَبَّهُۥۗ وَلَا تَكۡتُمُواْ ٱلشَّهَٰدَةَۚ وَمَن يَكۡتُمۡهَا فَإِنَّهُۥٓ ءَاثِمٞ قَلۡبُهُۥۗ وَٱللَّهُ بِمَا تَعۡمَلُونَ عَلِيمٞ","494":"وَءَاتُواْ ٱلۡيَتَٰمَىٰٓ أَمۡوَٰلَهُمۡۖ وَلَا تَتَبَدَّلُواْ ٱلۡخَبِيثَ بِٱلطَّيِّبِۖ وَلَا تَأۡكُلُوٓاْ أَمۡوَٰلَهُمۡ إِلَىٰٓ أَمۡوَٰلِكُمۡۚ إِنَّهُۥ كَانَ حُوبٗا كَبِيرٗا","495":"وَإِنۡ خِفۡتُمۡ أَلَّا تُقۡسِطُواْ فِي ٱلۡيَتَٰمَىٰ فَٱنكِحُواْ مَا طَابَ لَكُم مِّنَ ٱلنِّسَآءِ مَثۡنَىٰ وَثُلَٰثَ وَرُبَٰعَۖ فَإِنۡ خِفۡتُمۡ أَلَّا تَعۡدِلُواْ فَوَٰحِدَةً أَوۡ مَا مَلَكَتۡ أَيۡمَٰنُكُمۡۚ ذَٰلِكَ أَدۡنَىٰٓ أَلَّا تَعُولُواْ","496":"وَءَاتُواْ ٱلنِّسَآءَ صَدُقَٰتِهِنَّ نِحۡلَةٗۚ فَإِن طِبۡنَ لَكُمۡ عَن شَيۡءٖ مِّنۡهُ نَفۡسٗا فَكُلُوهُ هَنِيٓـٔٗا مَّرِيٓـٔٗا","498":"وَٱبۡتَلُواْ ٱلۡيَتَٰمَىٰ حَتَّىٰٓ إِذَا بَلَغُواْ ٱلنِّكَاحَ فَإِنۡ ءَانَسۡتُم مِّنۡهُمۡ رُشۡدٗا فَٱدۡفَعُوٓاْ إِلَيۡهِمۡ أَمۡوَٰلَهُمۡۖ وَلَا تَأۡكُلُوهَآ إِسۡرَافٗا وَبِدَارًا أَن يَكۡبَرُواْۚ وَمَن كَانَ غَنِيّٗا فَلۡيَسۡتَعۡفِفۡۖ وَمَن كَانَ فَقِيرٗا فَلۡيَأۡكُلۡ بِٱلۡمَعۡرُوفِۚ فَإِذَا دَفَعۡتُمۡ إِلَيۡهِمۡ أَمۡوَٰلَهُمۡ فَأَشۡهِدُواْ عَلَيۡهِمۡۚ وَكَفَىٰ بِٱللَّهِ حَسِيبٗا","503":"يُوصِيكُمُ ٱللَّهُ فِيٓ أَوۡلَٰدِكُمۡۖ لِلذَّكَرِ مِثۡلُ حَظِّ ٱلۡأُنثَيَيۡنِۚ فَإِن كُنَّ نِسَآءٗ فَوۡقَ ٱثۡنَتَيۡنِ فَلَهُنَّ ثُلُثَا مَا تَرَكَۖ وَإِن كَانَتۡ وَٰحِدَةٗ فَلَهَا ٱلنِّصۡفُۚ وَلِأَبَوَيۡهِ لِكُلِّ وَٰحِدٖ مِّنۡهُمَا ٱلسُّدُسُ مِمَّا تَرَكَ إِن كَانَ لَهُۥ وَلَدٞۚ فَإِن لَّمۡ يَكُن لَّهُۥ وَلَدٞ وَوَرِثَهُۥٓ أَبَوَاهُ فَلِأُمِّهِ ٱلثُّلُثُۚ فَإِن كَانَ لَهُۥٓ إِخۡوَةٞ فَلِأُمِّهِ ٱلسُّدُسُۚ مِنۢ بَعۡدِ وَصِيَّةٖ يُوصِي بِهَآ أَوۡ دَيۡنٍۗ ءَابَآؤُكُمۡ وَأَبۡنَآؤُكُمۡ لَا تَدۡرُونَ أَيُّهُمۡ أَقۡرَبُ لَكُمۡ نَفۡعٗاۚ فَرِيضَةٗ مِّنَ ٱللَّهِۗ إِنَّ ٱللَّهَ كَانَ عَلِيمًا حَكِيمٗا","504":"۞ وَلَكُمۡ نِصۡفُ مَا تَرَكَ أَزۡوَٰجُكُمۡ إِن لَّمۡ يَكُن لَّهُنَّ وَلَدٞۚ فَإِن كَانَ لَهُنَّ وَلَدٞ فَلَكُمُ ٱلرُّبُعُ مِمَّا تَرَكۡنَۚ مِنۢ بَعۡدِ وَصِيَّةٖ يُوصِينَ بِهَآ أَوۡ دَيۡنٖۚ وَلَهُنَّ ٱلرُّبُعُ مِمَّا تَرَكۡتُمۡ إِن لَّمۡ يَكُن لَّكُمۡ وَلَدٞۚ فَإِن كَانَ لَكُمۡ وَلَدٞ فَلَهُنَّ ٱلثُّمُنُ مِمَّا تَرَكۡتُمۚ مِّنۢ بَعۡدِ وَصِيَّةٖ تُوصُونَ بِهَآ أَوۡ دَيۡنٖۗ وَإِن كَانَ رَجُلٞ يُورَثُ كَلَٰلَةً أَوِ ٱمۡرَأَةٞ وَلَهُۥٓ أَخٌ أَوۡ أُخۡتٞ فَلِكُلِّ وَٰحِدٖ مِّنۡهُمَا ٱلسُّدُسُۚ فَإِن كَانُوٓاْ أَكۡثَرَ مِن ذَٰلِكَ فَهُمۡ شُرَكَآءُ فِي ٱلثُّلُثِۚ مِنۢ بَعۡدِ وَصِيَّةٖ يُوصَىٰ بِهَآ أَوۡ دَيۡنٍ غَيۡرَ مُضَآرّٖۚ وَصِيَّةٗ مِّنَ ٱللَّهِۗ وَٱللَّهُ عَلِيمٌ حَلِيمٞ","515":"حُرِّمَتۡ عَلَيۡكُمۡ أُمَّهَٰتُكُمۡ وَبَنَاتُكُمۡ وَأَخَوَٰتُكُمۡ وَعَمَّٰتُكُمۡ وَخَٰلَٰتُكُمۡ وَبَنَاتُ ٱلۡأَخِ وَبَنَاتُ ٱلۡأُخۡتِ وَأُمَّهَٰتُكُمُ ٱلَّٰتِيٓ أَرۡضَعۡنَكُمۡ وَأَخَوَٰتُكُم مِّنَ ٱلرَّضَٰعَةِ وَأُمَّهَٰتُ نِسَآئِكُمۡ وَرَبَٰٓئِبُكُمُ ٱلَّٰتِي فِي حُجُورِكُم مِّن نِّسَآئِكُمُ ٱلَّٰتِي دَخَلۡتُم بِهِنَّ فَإِن لَّمۡ تَكُونُواْ دَخَلۡتُم بِهِنَّ فَلَا جُنَاحَ عَلَيۡكُمۡ وَحَلَٰٓئِلُ أَبۡنَآئِكُمُ ٱلَّذِينَ مِنۡ أَصۡلَٰبِكُمۡ وَأَن تَجۡمَعُواْ بَيۡنَ ٱلۡأُخۡتَيۡنِ إِلَّا مَا قَدۡ سَلَفَۗ إِنَّ ٱللَّهَ كَانَ غَفُورٗا رَّحِيمٗا","516":"۞ وَٱلۡمُحۡصَنَٰتُ مِنَ ٱلنِّسَآءِ إِلَّا مَا مَلَكَتۡ أَيۡمَٰنُكُمۡۖ كِتَٰبَ ٱللَّهِ عَلَيۡكُمۡۚ وَأُحِلَّ لَكُم مَّا وَرَآءَ ذَٰلِكُمۡ أَن تَبۡتَغُواْ بِأَمۡوَٰلِكُم مُّحۡصِنِينَ غَيۡرَ مُسَٰفِحِينَۚ فَمَا ٱسۡتَمۡتَعۡتُم بِهِۦ مِنۡهُنَّ فَـَٔاتُوهُنَّ أُجُورَهُنَّ فَرِيضَةٗۚ وَلَا جُنَاحَ عَلَيۡكُمۡ فِيمَا تَرَٰضَيۡتُم بِهِۦ مِنۢ بَعۡدِ ٱلۡفَرِيضَةِۚ إِنَّ ٱللَّهَ كَانَ عَلِيمًا حَكِيمٗا","517":"وَمَن لَّمۡ يَسۡتَطِعۡ مِنكُمۡ طَوۡلًا أَن يَنكِحَ ٱلۡمُحۡصَنَٰتِ ٱلۡمُؤۡمِنَٰتِ فَمِن مَّا مَلَكَتۡ أَيۡمَٰنُكُم مِّن فَتَيَٰتِكُمُ ٱلۡمُؤۡمِنَٰتِۚ وَٱللَّهُ أَعۡلَمُ بِإِيمَٰنِكُمۚ بَعۡضُكُم مِّنۢ بَعۡضٖۚ فَٱنكِحُوهُنَّ بِإِذۡنِ أَهۡلِهِنَّ وَءَاتُوهُنَّ أُجُورَهُنَّ بِٱلۡمَعۡرُوفِ مُحۡصَنَٰتٍ غَيۡرَ مُسَٰفِحَٰتٖ وَلَا مُتَّخِذَٰتِ أَخۡدَانٖۚ فَإِذَآ أُحۡصِنَّ فَإِنۡ أَتَيۡنَ بِفَٰحِشَةٖ فَعَلَيۡهِنَّ نِصۡفُ مَا عَلَى ٱلۡمُحۡصَنَٰتِ مِنَ ٱلۡعَذَابِۚ ذَٰلِكَ لِمَنۡ خَشِيَ ٱلۡعَنَتَ مِنكُمۡۚ وَأَن تَصۡبِرُواْ خَيۡرٞ لَّكُمۡۗ وَٱللَّهُ غَفُورٞ رَّحِيمٞ","521":"يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تَأۡكُلُوٓاْ أَمۡوَٰلَكُم بَيۡنَكُم بِٱلۡبَٰطِلِ إِلَّآ أَن تَكُونَ تِجَٰرَةً عَن تَرَاضٖ مِّنكُمۡۚ وَلَا تَقۡتُلُوٓاْ أَنفُسَكُمۡۚ إِنَّ ٱللَّهَ كَانَ بِكُمۡ رَحِيمٗا","550":"۞ إِنَّ ٱللَّهَ يَأۡمُرُكُمۡ أَن تُؤَدُّواْ ٱلۡأَمَٰنَٰتِ إِلَىٰٓ أَهۡلِهَا وَإِذَا حَكَمۡتُم بَيۡنَ ٱلنَّاسِ أَن تَحۡكُمُواْ بِٱلۡعَدۡلِۚ إِنَّ ٱللَّهَ نِعِمَّا يَعِظُكُم بِهِۦٓۗ إِنَّ ٱللَّهَ كَانَ سَمِيعَۢا بَصِيرٗا","584":"وَمَا كَانَ لِمُؤۡمِنٍ أَن يَقۡتُلَ مُؤۡمِنًا إِلَّا خَطَـٔٗاۚ وَمَن قَتَلَ مُؤۡمِنًا خَطَـٔٗا فَتَحۡرِيرُ رَقَبَةٖ مُّؤۡمِنَةٖ وَدِيَةٞ مُّسَلَّمَةٌ إِلَىٰٓ أَهۡلِهِۦٓ إِلَّآ أَن يَصَّدَّقُواْۚ فَإِن كَانَ مِن قَوۡمٍ عَدُوّٖ لَّكُمۡ وَهُوَ مُؤۡمِنٞ فَتَحۡرِيرُ رَقَبَةٖ مُّؤۡمِنَةٖۖ وَإِن كَانَ مِن قَوۡمِۭ بَيۡنَكُمۡ وَبَيۡنَهُم مِّيثَٰقٞ فَدِيَةٞ مُّسَلَّمَةٌ إِلَىٰٓ أَهۡلِهِۦ وَتَحۡرِيرُ رَقَبَةٖ مُّؤۡمِنَةٖۖ فَمَن لَّمۡ يَجِدۡ فَصِيَامُ شَهۡرَيۡنِ مُتَتَابِعَيۡنِ تَوۡبَةٗ مِّنَ ٱللَّهِۗ وَكَانَ ٱللَّهُ عَلِيمًا حَكِيمٗا","585":"وَمَن يَقۡتُلۡ مُؤۡمِنٗا مُّتَعَمِّدٗا فَجَزَآؤُهُۥ جَهَنَّمُ خَٰلِدٗا فِيهَا وَغَضِبَ ٱللَّهُ عَلَيۡهِ وَلَعَنَهُۥ وَأَعَدَّ لَهُۥ عَذَابًا عَظِيمٗا","593":"وَإِذَا ضَرَبۡتُمۡ فِي ٱلۡأَرۡضِ فَلَيۡسَ عَلَيۡكُمۡ جُنَاحٌ أَن تَقۡصُرُواْ مِنَ ٱلصَّلَوٰةِ إِنۡ خِفۡتُمۡ أَن يَفۡتِنَكُمُ ٱلَّذِينَ كَفَرُوٓاْۚ إِنَّ ٱلۡكَٰفِرِينَ كَانُواْ لَكُمۡ عَدُوّٗا مُّبِينٗا","594":"وَإِذَا كُنتَ فِيهِمۡ فَأَقَمۡتَ لَهُمُ ٱلصَّلَوٰةَ فَلۡتَقُمۡ طَآئِفَةٞ مِّنۡهُم مَّعَكَ وَلۡيَأۡخُذُوٓاْ أَسۡلِحَتَهُمۡۖ فَإِذَا سَجَدُواْ فَلۡيَكُونُواْ مِن وَرَآئِكُمۡ وَلۡتَأۡتِ طَآئِفَةٌ أُخۡرَىٰ لَمۡ يُصَلُّواْ فَلۡيُصَلُّواْ مَعَكَ وَلۡيَأۡخُذُواْ حِذۡرَهُمۡ وَأَسۡلِحَتَهُمۡۗ وَدَّ ٱلَّذِينَ كَفَرُواْ لَوۡ تَغۡفُلُونَ عَنۡ أَسۡلِحَتِكُمۡ وَأَمۡتِعَتِكُمۡ فَيَمِيلُونَ عَلَيۡكُم مَّيۡلَةٗ وَٰحِدَةٗۚ وَلَا جُنَاحَ عَلَيۡكُمۡ إِن كَانَ بِكُمۡ أَذٗى مِّن مَّطَرٍ أَوۡ كُنتُم مَّرۡضَىٰٓ أَن تَضَعُوٓاْ أَسۡلِحَتَكُمۡۖ وَخُذُواْ حِذۡرَكُمۡۗ إِنَّ ٱللَّهَ أَعَدَّ لِلۡكَٰفِرِينَ عَذَابٗا مُّهِينٗا","595":"فَإِذَا قَضَيۡتُمُ ٱلصَّلَوٰةَ فَٱذۡكُرُواْ ٱللَّهَ قِيَٰمٗا وَقُعُودٗا وَعَلَىٰ جُنُوبِكُمۡۚ فَإِذَا ٱطۡمَأۡنَنتُمۡ فَأَقِيمُواْ ٱلصَّلَوٰةَۚ إِنَّ ٱلصَّلَوٰةَ كَانَتۡ عَلَى ٱلۡمُؤۡمِنِينَ كِتَٰبٗا مَّوۡقُوتٗا","621":"وَلَن تَسۡتَطِيعُوٓاْ أَن تَعۡدِلُواْ بَيۡنَ ٱلنِّسَآءِ وَلَوۡ حَرَصۡتُمۡۖ فَلَا تَمِيلُواْ كُلَّ ٱلۡمَيۡلِ فَتَذَرُوهَا كَٱلۡمُعَلَّقَةِۚ وَإِن تُصۡلِحُواْ وَتَتَّقُواْ فَإِنَّ ٱللَّهَ كَانَ غَفُورٗا رَّحِيمٗا","668":"يَسۡتَفۡتُونَكَ قُلِ ٱللَّهُ يُفۡتِيكُمۡ فِي ٱلۡكَلَٰلَةِۚ إِنِ ٱمۡرُؤٌاْ هَلَكَ لَيۡسَ لَهُۥ وَلَدٞ وَلَهُۥٓ أُخۡتٞ فَلَهَا نِصۡفُ مَا تَرَكَۚ وَهُوَ يَرِثُهَآ إِن لَّمۡ يَكُن لَّهَا وَلَدٞۚ فَإِن كَانَتَا ٱثۡنَتَيۡنِ فَلَهُمَا ٱلثُّلُثَانِ مِمَّا تَرَكَۚ وَإِن كَانُوٓاْ إِخۡوَةٗ رِّجَالٗا وَنِسَآءٗ فَلِلذَّكَرِ مِثۡلُ حَظِّ ٱلۡأُنثَيَيۡنِۗ يُبَيِّنُ ٱللَّهُ لَكُمۡ أَن تَضِلُّواْۗ وَٱللَّهُ بِكُلِّ شَيۡءٍ عَلِيمُۢ","669":"يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ أَوۡفُواْ بِٱلۡعُقُودِۚ أُحِلَّتۡ لَكُم بَهِيمَةُ ٱلۡأَنۡعَٰمِ إِلَّا مَا يُتۡلَىٰ عَلَيۡكُمۡ غَيۡرَ مُحِلِّي ٱلصَّيۡدِ وَأَنتُمۡ حُرُمٌۗ إِنَّ ٱللَّهَ يَحۡكُمُ مَا يُرِيدُ","671":"حُرِّمَتۡ عَلَيۡكُمُ ٱلۡمَيۡتَةُ وَٱلدَّمُ وَلَحۡمُ ٱلۡخِنزِيرِ وَمَآ أُهِلَّ لِغَيۡرِ ٱللَّهِ بِهِۦ وَٱلۡمُنۡخَنِقَةُ وَٱلۡمَوۡقُوذَةُ وَٱلۡمُتَرَدِّيَةُ وَٱلنَّطِيحَةُ وَمَآ أَكَلَ ٱلسَّبُعُ إِلَّا مَا ذَكَّيۡتُمۡ وَمَا ذُبِحَ عَلَى ٱلنُّصُبِ وَأَن تَسۡتَقۡسِمُواْ بِٱلۡأَزۡلَٰمِۚ ذَٰلِكُمۡ فِسۡقٌۗ ٱلۡيَوۡمَ يَئِسَ ٱلَّذِينَ كَفَرُواْ مِن دِينِكُمۡ فَلَا تَخۡشَوۡهُمۡ وَٱخۡشَوۡنِۚ ٱلۡيَوۡمَ أَكۡمَلۡتُ لَكُمۡ دِينَكُمۡ وَأَتۡمَمۡتُ عَلَيۡكُمۡ نِعۡمَتِي وَرَضِيتُ لَكُمُ ٱلۡإِسۡلَٰمَ دِينٗاۚ فَمَنِ ٱضۡطُرَّ فِي مَخۡمَصَةٍ غَيۡرَ مُتَجَانِفٖ لِّإِثۡمٖ فَإِنَّ ٱللَّهَ غَفُورٞ رَّحِيمٞ","672":"يَسۡـَٔلُونَكَ مَاذَآ أُحِلَّ لَهُمۡۖ قُلۡ أُحِلَّ لَكُمُ ٱلطَّيِّبَٰتُ وَمَا عَلَّمۡتُم مِّنَ ٱلۡجَوَارِحِ مُكَلِّبِينَ تُعَلِّمُونَهُنَّ مِمَّا عَلَّمَكُمُ ٱللَّهُۖ فَكُلُواْ مِمَّآ أَمۡسَكۡنَ عَلَيۡكُمۡ وَٱذۡكُرُواْ ٱسۡمَ ٱللَّهِ عَلَيۡهِۖ وَٱتَّقُواْ ٱللَّهَۚ إِنَّ ٱللَّهَ سَرِيعُ ٱلۡحِسَابِ","673":"ٱلۡيَوۡمَ أُحِلَّ لَكُمُ ٱلطَّيِّبَٰتُۖ وَطَعَامُ ٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ حِلّٞ لَّكُمۡ وَطَعَامُكُمۡ حِلّٞ لَّهُمۡۖ وَٱلۡمُحۡصَنَٰتُ مِنَ ٱلۡمُؤۡمِنَٰتِ وَٱلۡمُحۡصَنَٰتُ مِنَ ٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ مِن قَبۡلِكُمۡ إِذَآ ءَاتَيۡتُمُوهُنَّ أُجُورَهُنَّ مُحۡصِنِينَ غَيۡرَ مُسَٰفِحِينَ وَلَا مُتَّخِذِيٓ أَخۡدَانٖۗ وَمَن يَكۡفُرۡ بِٱلۡإِيمَٰنِ فَقَدۡ حَبِطَ عَمَلُهُۥ وَهُوَ فِي ٱلۡأٓخِرَةِ مِنَ ٱلۡخَٰسِرِينَ","674":"يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ إِذَا قُمۡتُمۡ إِلَى ٱلصَّلَوٰةِ فَٱغۡسِلُواْ وُجُوهَكُمۡ وَأَيۡدِيَكُمۡ إِلَى ٱلۡمَرَافِقِ وَٱمۡسَحُواْ بِرُءُوسِكُمۡ وَأَرۡجُلَكُمۡ إِلَى ٱلۡكَعۡبَيۡنِۚ وَإِن كُنتُمۡ جُنُبٗا فَٱطَّهَّرُواْۚ وَإِن كُنتُم مَّرۡضَىٰٓ أَوۡ عَلَىٰ سَفَرٍ أَوۡ جَآءَ أَحَدٞ مِّنكُم مِّنَ ٱلۡغَآئِطِ أَوۡ لَٰمَسۡتُمُ ٱلنِّسَآءَ فَلَمۡ تَجِدُواْ مَآءٗ فَتَيَمَّمُواْ صَعِيدٗا طَيِّبٗا فَٱمۡسَحُواْ بِوُجُوهِكُمۡ وَأَيۡدِيكُم مِّنۡهُۚ مَا يُرِيدُ ٱللَّهُ لِيَجۡعَلَ عَلَيۡكُم مِّنۡ حَرَجٖ وَلَٰكِن يُرِيدُ لِيُطَهِّرَكُمۡ وَلِيُتِمَّ نِعۡمَتَهُۥ عَلَيۡكُمۡ لَعَلَّكُمۡ تَشۡكُرُونَ","701":"إِنَّمَا جَزَٰٓؤُاْ ٱلَّذِينَ يُحَارِبُونَ ٱللَّهَ وَرَسُولَهُۥ وَيَسۡعَوۡنَ فِي ٱلۡأَرۡضِ فَسَادًا أَن يُقَتَّلُوٓاْ أَوۡ يُصَلَّبُوٓاْ أَوۡ تُقَطَّعَ أَيۡدِيهِمۡ وَأَرۡجُلُهُم مِّنۡ خِلَٰفٍ أَوۡ يُنفَوۡاْ مِنَ ٱلۡأَرۡضِۚ ذَٰلِكَ لَهُمۡ خِزۡيٞ فِي ٱلدُّنۡيَاۖ وَلَهُمۡ فِي ٱلۡأٓخِرَةِ عَذَابٌ عَظِيمٌ","702":"إِلَّا ٱلَّذِينَ تَابُواْ مِن قَبۡلِ أَن تَقۡدِرُواْ عَلَيۡهِمۡۖ فَٱعۡلَمُوٓاْ أَنَّ ٱللَّهَ غَفُورٞ رَّحِيمٞ","706":"وَٱلسَّارِقُ وَٱلسَّارِقَةُ فَٱقۡطَعُوٓاْ أَيۡدِيَهُمَا جَزَآءَۢ بِمَا كَسَبَا نَكَٰلٗا مِّنَ ٱللَّهِۗ وَٱللَّهُ عَزِيزٌ حَكِيمٞ","707":"فَمَن تَابَ مِنۢ بَعۡدِ ظُلۡمِهِۦ وَأَصۡلَحَ فَإِنَّ ٱللَّهَ يَتُوبُ عَلَيۡهِۚ إِنَّ ٱللَّهَ غَفُورٞ رَّحِيمٌ","757":"لَا يُؤَاخِذُكُمُ ٱللَّهُ بِٱللَّغۡوِ فِيٓ أَيۡمَٰنِكُمۡ وَلَٰكِن يُؤَاخِذُكُم بِمَا عَقَّدتُّمُ ٱلۡأَيۡمَٰنَۖ فَكَفَّٰرَتُهُۥٓ إِطۡعَامُ عَشَرَةِ مَسَٰكِينَ مِنۡ أَوۡسَطِ مَا تُطۡعِمُونَ أَهۡلِيكُمۡ أَوۡ كِسۡوَتُهُمۡ أَوۡ تَحۡرِيرُ رَقَبَةٖۖ فَمَن لَّمۡ يَجِدۡ فَصِيَامُ ثَلَٰثَةِ أَيَّامٖۚ ذَٰلِكَ كَفَّٰرَةُ أَيۡمَٰنِكُمۡ إِذَا حَلَفۡتُمۡۚ وَٱحۡفَظُوٓاْ أَيۡمَٰنَكُمۡۚ كَذَٰلِكَ يُبَيِّنُ ٱللَّهُ لَكُمۡ ءَايَٰتِهِۦ لَعَلَّكُمۡ تَشۡكُرُونَ","758":"يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ إِنَّمَا ٱلۡخَمۡرُ وَٱلۡمَيۡسِرُ وَٱلۡأَنصَابُ وَٱلۡأَزۡلَٰمُ رِجۡسٞ مِّنۡ عَمَلِ ٱلشَّيۡطَٰنِ فَٱجۡتَنِبُوهُ لَعَلَّكُمۡ تُفۡلِحُونَ","759":"إِنَّمَا يُرِيدُ ٱلشَّيۡطَٰنُ أَن يُوقِعَ بَيۡنَكُمُ ٱلۡعَدَٰوَةَ وَٱلۡبَغۡضَآءَ فِي ٱلۡخَمۡرِ وَٱلۡمَيۡسِرِ وَيَصُدَّكُمۡ عَن ذِكۡرِ ٱللَّهِ وَعَنِ ٱلصَّلَوٰةِۖ فَهَلۡ أَنتُم مُّنتَهُونَ","906":"فَكُلُواْ مِمَّا ذُكِرَ ٱسۡمُ ٱللَّهِ عَلَيۡهِ إِن كُنتُم بِـَٔايَٰتِهِۦ مُؤۡمِنِينَ","907":"وَمَا لَكُمۡ أَلَّا تَأۡكُلُواْ مِمَّا ذُكِرَ ٱسۡمُ ٱللَّهِ عَلَيۡهِ وَقَدۡ فَصَّلَ لَكُم مَّا حَرَّمَ عَلَيۡكُمۡ إِلَّا مَا ٱضۡطُرِرۡتُمۡ إِلَيۡهِۗ وَإِنَّ كَثِيرٗا لَّيُضِلُّونَ بِأَهۡوَآئِهِم بِغَيۡرِ عِلۡمٍۚ إِنَّ رَبَّكَ هُوَ أَعۡلَمُ بِٱلۡمُعۡتَدِينَ","909":"وَلَا تَأۡكُلُواْ مِمَّا لَمۡ يُذۡكَرِ ٱسۡمُ ٱللَّهِ عَلَيۡهِ وَإِنَّهُۥ لَفِسۡقٞۗ وَإِنَّ ٱلشَّيَٰطِينَ لَيُوحُونَ إِلَىٰٓ أَوۡلِيَآئِهِمۡ لِيُجَٰدِلُوكُمۡۖ وَإِنۡ أَطَعۡتُمُوهُمۡ إِنَّكُمۡ لَمُشۡرِكُونَ","933":"قُل لَّآ أَجِدُ فِي مَآ أُوحِيَ إِلَيَّ مُحَرَّمًا عَلَىٰ طَاعِمٖ يَطۡعَمُهُۥٓ إِلَّآ أَن يَكُونَ مَيۡتَةً أَوۡ دَمٗا مَّسۡفُوحًا أَوۡ لَحۡمَ خِنزِيرٖ فَإِنَّهُۥ رِجۡسٌ أَوۡ فِسۡقًا أُهِلَّ لِغَيۡرِ ٱللَّهِ بِهِۦۚ فَمَنِ ٱضۡطُرَّ غَيۡرَ بَاغٖ وَلَا عَادٖ فَإِنَّ رَبَّكَ غَفُورٞ رَّحِيمٞ","984":"۞ يَٰبَنِيٓ ءَادَمَ خُذُواْ زِينَتَكُمۡ عِندَ كُلِّ مَسۡجِدٖ وَكُلُواْ وَٱشۡرَبُواْ وَلَا تُسۡرِفُوٓاْۚ إِنَّهُۥ لَا يُحِبُّ ٱلۡمُسۡرِفِينَ","1240":"وَإِنۡ أَحَدٞ مِّنَ ٱلۡمُشۡرِكِينَ ٱسۡتَجَارَكَ فَأَجِرۡهُ حَتَّىٰ يَسۡمَعَ كَلَٰمَ ٱللَّهِ ثُمَّ أَبۡلِغۡهُ مَأۡمَنَهُۥۚ ذَٰلِكَ بِأَنَّهُمۡ قَوۡمٞ لَّا يَعۡلَمُونَ","2106":"أَقِمِ ٱلصَّلَوٰةَ لِدُلُوكِ ٱلشَّمۡسِ إِلَىٰ غَسَقِ ٱلَّيۡلِ وَقُرۡءَانَ ٱلۡفَجۡرِۖ إِنَّ قُرۡءَانَ ٱلۡفَجۡرِ كَانَ مَشۡهُودٗا","2792":"ٱلزَّانِيَةُ وَٱلزَّانِي فَٱجۡلِدُواْ كُلَّ وَٰحِدٖ مِّنۡهُمَا مِاْئَةَ جَلۡدَةٖۖ وَلَا تَأۡخُذۡكُم بِهِمَا رَأۡفَةٞ فِي دِينِ ٱللَّهِ إِن كُنتُمۡ تُؤۡمِنُونَ بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِۖ وَلۡيَشۡهَدۡ عَذَابَهُمَا طَآئِفَةٞ مِّنَ ٱلۡمُؤۡمِنِينَ","2793":"ٱلزَّانِي لَا يَنكِحُ إِلَّا زَانِيَةً أَوۡ مُشۡرِكَةٗ وَٱلزَّانِيَةُ لَا يَنكِحُهَآ إِلَّا زَانٍ أَوۡ مُشۡرِكٞۚ وَحُرِّمَ ذَٰلِكَ عَلَى ٱلۡمُؤۡمِنِينَ","2794":"وَٱلَّذِينَ يَرۡمُونَ ٱلۡمُحۡصَنَٰتِ ثُمَّ لَمۡ يَأۡتُواْ بِأَرۡبَعَةِ شُهَدَآءَ فَٱجۡلِدُوهُمۡ ثَمَٰنِينَ جَلۡدَةٗ وَلَا تَقۡبَلُواْ لَهُمۡ شَهَٰدَةً أَبَدٗاۚ وَأُوْلَٰٓئِكَ هُمُ ٱلۡفَٰسِقُونَ","2795":"إِلَّا ٱلَّذِينَ تَابُواْ مِنۢ بَعۡدِ ذَٰلِكَ وَأَصۡلَحُواْ فَإِنَّ ٱللَّهَ غَفُورٞ رَّحِيمٞ","2796":"وَٱلَّذِينَ يَرۡمُونَ أَزۡوَٰجَهُمۡ وَلَمۡ يَكُن لَّهُمۡ شُهَدَآءُ إِلَّآ أَنفُسُهُمۡ فَشَهَٰدَةُ أَحَدِهِمۡ أَرۡبَعُ شَهَٰدَٰتِۭ بِٱللَّهِ إِنَّهُۥ لَمِنَ ٱلصَّٰدِقِينَ","2797":"وَٱلۡخَٰمِسَةُ أَنَّ لَعۡنَتَ ٱللَّهِ عَلَيۡهِ إِن كَانَ مِنَ ٱلۡكَٰذِبِينَ","2798":"وَيَدۡرَؤُاْ عَنۡهَا ٱلۡعَذَابَ أَن تَشۡهَدَ أَرۡبَعَ شَهَٰدَٰتِۭ بِٱللَّهِ إِنَّهُۥ لَمِنَ ٱلۡكَٰذِبِينَ","2799":"وَٱلۡخَٰمِسَةَ أَنَّ غَضَبَ ٱللَّهِ عَلَيۡهَآ إِن كَانَ مِنَ ٱلصَّٰدِقِينَ","2820":"قُل لِّلۡمُؤۡمِنِينَ يَغُضُّواْ مِنۡ أَبۡصَٰرِهِمۡ وَيَحۡفَظُواْ فُرُوجَهُمۡۚ ذَٰلِكَ أَزۡكَىٰ لَهُمۡۚ إِنَّ ٱللَّهَ خَبِيرُۢ بِمَا يَصۡنَعُونَ","2821":"وَقُل لِّلۡمُؤۡمِنَٰتِ يَغۡضُضۡنَ مِنۡ أَبۡصَٰرِهِنَّ وَيَحۡفَظۡنَ فُرُوجَهُنَّ وَلَا يُبۡدِينَ زِينَتَهُنَّ إِلَّا مَا ظَهَرَ مِنۡهَاۖ وَلۡيَضۡرِبۡنَ بِخُمُرِهِنَّ عَلَىٰ جُيُوبِهِنَّۖ وَلَا يُبۡدِينَ زِينَتَهُنَّ إِلَّا لِبُعُولَتِهِنَّ أَوۡ ءَابَآئِهِنَّ أَوۡ ءَابَآءِ بُعُولَتِهِنَّ أَوۡ أَبۡنَآئِهِنَّ أَوۡ أَبۡنَآءِ بُعُولَتِهِنَّ أَوۡ إِخۡوَٰنِهِنَّ أَوۡ بَنِيٓ إِخۡوَٰنِهِنَّ أَوۡ بَنِيٓ أَخَوَٰتِهِنَّ أَوۡ نِسَآئِهِنَّ أَوۡ مَا مَلَكَتۡ أَيۡمَٰنُهُنَّ أَوِ ٱلتَّٰبِعِينَ غَيۡرِ أُوْلِي ٱلۡإِرۡبَةِ مِنَ ٱلرِّجَالِ أَوِ ٱلطِّفۡلِ ٱلَّذِينَ لَمۡ يَظۡهَرُواْ عَلَىٰ عَوۡرَٰتِ ٱلنِّسَآءِۖ وَلَا يَضۡرِبۡنَ بِأَرۡجُلِهِنَّ لِيُعۡلَمَ مَا يُخۡفِينَ مِن زِينَتِهِنَّۚ وَتُوبُوٓاْ إِلَى ٱللَّهِ جَمِيعًا أَيُّهَ ٱلۡمُؤۡمِنُونَ لَعَلَّكُمۡ تُفۡلِحُونَ","3591":"يَٰٓأَيُّهَا ٱلنَّبِيُّ قُل لِّأَزۡوَٰجِكَ وَبَنَاتِكَ وَنِسَآءِ ٱلۡمُؤۡمِنِينَ يُدۡنِينَ عَلَيۡهِنَّ مِن جَلَٰبِيبِهِنَّۚ ذَٰلِكَ أَدۡنَىٰٓ أَن يُعۡرَفۡنَ فَلَا يُؤۡذَيۡنَۗ وَكَانَ ٱللَّهُ غَفُورٗا رَّحِيمٗا","4620":"وَإِن طَآئِفَتَانِ مِنَ ٱلۡمُؤۡمِنِينَ ٱقۡتَتَلُواْ فَأَصۡلِحُواْ بَيۡنَهُمَاۖ فَإِنۢ بَغَتۡ إِحۡدَىٰهُمَا عَلَى ٱلۡأُخۡرَىٰ فَقَٰتِلُواْ ٱلَّتِي تَبۡغِي حَتَّىٰ تَفِيٓءَ إِلَىٰٓ أَمۡرِ ٱللَّهِۚ فَإِن فَآءَتۡ فَأَصۡلِحُواْ بَيۡنَهُمَا بِٱلۡعَدۡلِ وَأَقۡسِطُوٓاْۖ إِنَّ ٱللَّهَ يُحِبُّ ٱلۡمُقۡسِطِينَ","4621":"إِنَّمَا ٱلۡمُؤۡمِنُونَ إِخۡوَةٞ فَأَصۡلِحُواْ بَيۡنَ أَخَوَيۡكُمۡۚ وَٱتَّقُواْ ٱللَّهَ لَعَلَّكُمۡ تُرۡحَمُونَ","5105":"ٱلَّذِينَ يُظَٰهِرُونَ مِنكُم مِّن نِّسَآئِهِم مَّا هُنَّ أُمَّهَٰتِهِمۡۖ إِنۡ أُمَّهَٰتُهُمۡ إِلَّا ٱلَّٰٓـِٔي وَلَدۡنَهُمۡۚ وَإِنَّهُمۡ لَيَقُولُونَ مُنكَرٗا مِّنَ ٱلۡقَوۡلِ وَزُورٗاۚ وَإِنَّ ٱللَّهَ لَعَفُوٌّ غَفُورٞ","5106":"وَٱلَّذِينَ يُظَٰهِرُونَ مِن نِّسَآئِهِمۡ ثُمَّ يَعُودُونَ لِمَا قَالُواْ فَتَحۡرِيرُ رَقَبَةٖ مِّن قَبۡلِ أَن يَتَمَآسَّاۚ ذَٰلِكُمۡ تُوعَظُونَ بِهِۦۚ وَٱللَّهُ بِمَا تَعۡمَلُونَ خَبِيرٞ","5107":"فَمَن لَّمۡ يَجِدۡ فَصِيَامُ شَهۡرَيۡنِ مُتَتَابِعَيۡنِ مِن قَبۡلِ أَن يَتَمَآسَّاۖ فَمَن لَّمۡ يَسۡتَطِعۡ فَإِطۡعَامُ سِتِّينَ مِسۡكِينٗاۚ ذَٰلِكَ لِتُؤۡمِنُواْ بِٱللَّهِ وَرَسُولِهِۦۚ وَتِلۡكَ حُدُودُ ٱللَّهِۗ وَلِلۡكَٰفِرِينَ عَذَابٌ أَلِيمٌ","5185":"يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ إِذَا نُودِيَ لِلصَّلَوٰةِ مِن يَوۡمِ ٱلۡجُمُعَةِ فَٱسۡعَوۡاْ إِلَىٰ ذِكۡرِ ٱللَّهِ وَذَرُواْ ٱلۡبَيۡعَۚ ذَٰلِكُمۡ خَيۡرٞ لَّكُمۡ إِن كُنتُمۡ تَعۡلَمُونَ","5186":"فَإِذَا قُضِيَتِ ٱلصَّلَوٰةُ فَٱنتَشِرُواْ فِي ٱلۡأَرۡضِ وَٱبۡتَغُواْ مِن فَضۡلِ ٱللَّهِ وَٱذۡكُرُواْ ٱللَّهَ كَثِيرٗا لَّعَلَّكُمۡ تُفۡلِحُونَ","5217":"يَٰٓأَيُّهَا ٱلنَّبِيُّ إِذَا طَلَّقۡتُمُ ٱلنِّسَآءَ فَطَلِّقُوهُنَّ لِعِدَّتِهِنَّ وَأَحۡصُواْ ٱلۡعِدَّةَۖ وَٱتَّقُواْ ٱللَّهَ رَبَّكُمۡۖ لَا تُخۡرِجُوهُنَّ مِنۢ بُيُوتِهِنَّ وَلَا يَخۡرُجۡنَ إِلَّآ أَن يَأۡتِينَ بِفَٰحِشَةٖ مُّبَيِّنَةٖۚ وَتِلۡكَ حُدُودُ ٱللَّهِۚ وَمَن يَتَعَدَّ حُدُودَ ٱللَّهِ فَقَدۡ ظَلَمَ نَفۡسَهُۥۚ لَا تَدۡرِي لَعَلَّ ٱللَّهَ يُحۡدِثُ بَعۡدَ ذَٰلِكَ أَمۡرٗا","5220":"وَٱلَّٰٓـِٔي يَئِسۡنَ مِنَ ٱلۡمَحِيضِ مِن نِّسَآئِكُمۡ إِنِ ٱرۡتَبۡتُمۡ فَعِدَّتُهُنَّ ثَلَٰثَةُ أَشۡهُرٖ وَٱلَّٰٓـِٔي لَمۡ يَحِضۡنَۚ وَأُوْلَٰتُ ٱلۡأَحۡمَالِ أَجَلُهُنَّ أَن يَضَعۡنَ حَمۡلَهُنَّۚ وَمَن يَتَّقِ ٱللَّهَ يَجۡعَل لَّهُۥ مِنۡ أَمۡرِهِۦ يُسۡرٗا","5222":"أَسۡكِنُوهُنَّ مِنۡ حَيۡثُ سَكَنتُم مِّن وُجۡدِكُمۡ وَلَا تُضَآرُّوهُنَّ لِتُضَيِّقُواْ عَلَيۡهِنَّۚ وَإِن كُنَّ أُوْلَٰتِ حَمۡلٖ فَأَنفِقُواْ عَلَيۡهِنَّ حَتَّىٰ يَضَعۡنَ حَمۡلَهُنَّۚ فَإِنۡ أَرۡضَعۡنَ لَكُمۡ فَـَٔاتُوهُنَّ أُجُورَهُنَّ وَأۡتَمِرُواْ بَيۡنَكُم بِمَعۡرُوفٖۖ وَإِن تَعَاسَرۡتُمۡ فَسَتُرۡضِعُ لَهُۥٓ أُخۡرَىٰ","5223":"لِيُنفِقۡ ذُو سَعَةٖ مِّن سَعَتِهِۦۖ وَمَن قُدِرَ عَلَيۡهِ رِزۡقُهُۥ فَلۡيُنفِقۡ مِمَّآ ءَاتَىٰهُ ٱللَّهُۚ لَا يُكَلِّفُ ٱللَّهُ نَفۡسًا إِلَّا مَآ ءَاتَىٰهَاۚ سَيَجۡعَلُ ٱللَّهُ بَعۡدَ عُسۡرٖ يُسۡرٗا"},"nay":84,"nq":76};
